            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "charAt(") == 1) {
          open = k + 7;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_char_at(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "slice(") == 1) {
          open = k + 6;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_slice(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "length") == 1) {
          out = _lia_cat(out ,  "_lia_len(");
          out = _lia_cat(out ,  id);
          out = _lia_cat(out ,  ")");
          i = k + 7;
          continue;
        }
        if (starts_lit(s, k + 1, "len") == 1  and  (k + 4 >= n  or  is_ident(_lia_char_code_at(s, k + 4)) == false)) {
          out = _lia_cat(out ,  "_lia_len(");
          out = _lia_cat(out ,  id);
          out = _lia_cat(out ,  ")");
          i = k + 4;
          continue;
        }
        if (starts_lit(s, k + 1, "push(") == 1) {
          open = k + 5;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_list_push(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "get(") == 1) {
          open = k + 4;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_list_get(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "set(") == 1) {
          open = k + 4;
          cl = match_paren(s, open);
          if (cl > open) {
            out = _lia_cat(out ,  "_lia_list_set(");
            out = _lia_cat(out ,  id);
            out = _lia_cat(out ,  ", ");
            out = _lia_cat(out ,  slice2(s, open + 1, cl));
            out = _lia_cat(out ,  ")");
            i = cl + 1;
            continue;
          }
        }
        if (starts_lit(s, k + 1, "pop()") == 1) {
