        }
      }
      out = _lia_cat(out ,  id);
      i = i + _lia_len(id);
      continue;
    }
    chs = _lia_char_at(s, i);
    out = _lia_cat(out ,  chs);
    i = i + 1;
  }
  return out;

}

pub fn atom_is_str(a: []const u8) i64 {
    var c: i64 = 0;

  if (_lia_len(a) == 0) { return 0 ;}
  c = _lia_char_code_at(a, 0);
  if (c == 32  or  c == 9) { return atom_is_str(slice2(a, 1, _lia_len(a))) ;}
  if (c == 34) { return 1 ;}
  if (starts_lit(a, 0, "_lia_len") == 1  or  starts_lit(a, 0, "_lia_char_code_at") == 1) { return 0 ;}
  if (starts_lit(a, 0, "_lia_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "slice2") == 1) { return 1 ;}
  if (starts_lit(a, 0, "read_ident") == 1) { return 1 ;}
  if (starts_lit(a, 0, "out") == 1  and  (_lia_len(a) == 3  or  _lia_char_code_at(a, 3) < 48  or  _lia_char_code_at(a, 3) > 122)) { return 1 ;}
  if (starts_lit(a, 0, "id") == 1  and  _lia_len(a) == 2) { return 1 ;}
  if (starts_lit(a, 0, "src") == 1  and  _lia_len(a) == 3) { return 1 ;}
  if (starts_lit(a, 0, "body") == 1) { return 1 ;}
  if (starts_lit(a, 0, "params") == 1) { return 1 ;}
  if (starts_lit(a, 0, "names") == 1) { return 1 ;}
  if (starts_lit(a, 0, "chs") == 1) { return 1 ;}
  if (starts_lit(a, 0, "js_p") == 1) { return 1 ;}
  if (starts_lit(a, 0, "zig_params") == 1) { return 1 ;}
  if (starts_lit(a, 0, "regions") == 1) { return 1 ;}
  if (starts_lit(a, 0, "chunk") == 1) { return 1 ;}
  if (starts_lit(a, 0, "head") == 1) { return 1 ;}
  if (starts_lit(a, 0, "rgs_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "q()") == 1) { return 1 ;}
  if (starts_lit(a, 0, "csv_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "read_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "curfn") == 1) { return 1 ;}
  if (starts_lit(a, 0, "v") == 1  and  _lia_len(a) == 1) { return 1 ;}
  if (starts_lit(a, 0, "lines") == 1) { return 1 ;}
  if (starts_lit(a, 0, "nm") == 1  and  _lia_len(a) == 2) { return 1 ;}
  if (starts_lit(a, 0, "reason") == 1) { return 1 ;}
  if (starts_lit(a, 0, "pass") == 1) { return 1 ;}
  if (starts_lit(a, 0, "last") == 1) { return 1 ;}
  if (starts_lit(a, 0, "jss_") == 1) { return 1 ;}
  if (starts_lit(a, 0, "cfs_") == 1) { return 1 ;}
  return 0;

}

pub fn atom_is_num(a: []const u8) i64 {
    var c: i64 = 0;

  if (_lia_len(a) == 0) { return 0 ;}
  c = _lia_char_code_at(a, 0);
  if (c == 32  or  c == 9) { return atom_is_num(slice2(a, 1, _lia_len(a))) ;}
  if (c >= 48  and  c <= 57) { return 1 ;}
  if (c == 45) { return 1 ;}
  if (starts_lit(a, 0, "@as") == 1) { return 1 ;}
  if (starts_lit(a, 0, "_lia_char_code") == 1) { return 1 ;}
  if (starts_lit(a, 0, "_lia_len") == 1) { return 1 ;}
  if (starts_lit(a, 0, "_lia_list_len") == 1) { return 1 ;}
  return 0;

}

pub fn rewrite_plus(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var L: i64 = 0;
    var R: i64 = 0;
    var left: []const u8 = "";
    var right: []const u8 = "";
    var cut: i64 = 0;
    var take: i64 = 0;
    var c: i64 = 0;
    var id: []const u8 = "";
    var cl: i64 = 0;

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  L = 0;
  R = 0;
  left = "";
  right = "";
  cut = 0;
  take = 0;
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    if (_lia_char_code_at(s, i) == 43) {
      L = i;
      while (L > 0) {
        c = _lia_char_code_at(s, L - 1);
        if (c == 32  or  c == 9) { L = L - 1 ;}
         else { break ;}
      }
      while (L > 0  and  is_ident(_lia_char_code_at(s, L - 1))) { L = L - 1 ;}
      R = skip_ws(s, i + 1);
      if (R < n  and  _lia_char_code_at(s, R) == 34) {
        R = R + 1;
        while (R < n  and  _lia_char_code_at(s, R) != 34) { R = R + 1 ;}
        if (R < n) { R = R + 1 ;}
      }
       else {
        id = read_ident(s, R);
        if (_lia_len(id) > 0) {
          R = R + _lia_len(id);
          if (R < n  and  _lia_char_code_at(s, R) == 40) {
            cl = match_paren(s, R);
            if (cl > R) { R = cl + 1 ;}
          }
        }
         else { R = R + 1 ;}
      }
      left = slice2(s, L, i);
      right = slice2(s, i + 1, R);
      if (atom_is_str(left) == 1  or  atom_is_str(right) == 1) {
        if (atom_is_num(left) == 0  or  atom_is_num(right) == 0) {
          take = i - L;
          cut = _lia_len(out) - take;
          if (cut < 0) { cut = 0 ;}
          out = slice2(out, 0, cut);
          out = _lia_cat(out ,  "_lia_cat(");
          out = _lia_cat(out ,  left);
          out = _lia_cat(out ,  ", ");
          out = _lia_cat(out ,  right);
          out = _lia_cat(out ,  ")");
          i = R;
          continue;
        }
      }
    }
    chs = _lia_char_at(s, i);
    out = _lia_cat(out ,  chs);
    i = i + 1;
  }
  return out;

}

pub fn rewrite_semi(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var t: i64 = 0;
    var prev: i64 = 0;

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  t = 0;
  prev = 0;
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    if (_lia_char_code_at(s, i) == 125) {
      t = _lia_len(out);
      while (t > 0) {
        prev = _lia_char_code_at(out, t - 1);
        if (prev == 32  or  prev == 9  or  prev == 10  or  prev == 13) { t = t - 1 ;}
         else { break ;}
      }
      if (t > 0) {
        prev = _lia_char_code_at(out, t - 1);
        if (prev != 59  and  prev != 123  and  prev != 125) { out = _lia_cat(out ,  ";") ;}
      }
      out = _lia_cat(out ,  "}");
      i = i + 1;
    }
     else {
      chs = _lia_char_at(s, i);
      out = _lia_cat(out ,  chs);
      i = i + 1;
    }
  }
  return out;

}

pub fn zig_pipe(body: []const u8) []const u8 {

  return rewrite_arr(kw_space(andor(rewrite_semi(rewrite_plus(rewrite_js_methods(rewrite_body(rewrite_cfor(rewrite_match(body)))))))));

}

pub fn emit_fns(src: []const u8, lang: i64) []const u8 {
    var out: []const u8 = "";
    var name: []const u8 = "";
    var params: []const u8 = "";
    var body: []const u8 = "";
    var js_p: []const u8 = "";
    var zig_params: []const u8 = "";
    var id: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var p: i64 = 0;
    var close_p: i64 = 0;
    var b: i64 = 0;
    var close_b: i64 = 0;
    var k: i64 = 0;
    var pn: i64 = 0;
    var seen: i64 = 0;

  out = "";
  name = "";
  params = "";
  body = "";
  js_p = "";
  zig_params = "";
  id = "";
  n = _lia_len(src);
  i = 0;
  if (lang == 0) { out = "/* generated by lin-rewrite 2.0.0 */\n" ;}
   else { out = "// generated by LIN Zig bootstrap\n" ;}
  while (i < n) {
    i = skip_ws(src, i);
    if (i >= n) { return out ;}
    if (_lia_char_code_at(src, i) == 33  and  (i + 1 >= n  or  _lia_char_code_at(src, i + 1) != 61)) {
      name = read_ident(src, i + 1);
      if (_lia_len(name) > 0) {
        p = skip_ws(src, i + 1 + _lia_len(name));
        if (p < n  and  _lia_char_code_at(src, p) == 40) {
          close_p = p + 1;
          while (close_p < n  and  _lia_char_code_at(src, close_p) != 41) { close_p = close_p + 1 ;}
          params = slice2(src, p + 1, close_p);
          b = find_brace(src, close_p + 1);
          if (b >= 0) {
            close_b = match_brace(src, b);
            if (close_b > b) {
              body = slice2(src, b + 1, close_b);
              js_p = js_params(params);
              if (lang == 0) {
                out = _lia_cat(out ,  "function ");
                out = _lia_cat(out ,  name);
                out = _lia_cat(out ,  "(");
                out = _lia_cat(out ,  js_p);
                out = _lia_cat(out ,  "){");
                out = _lia_cat(out ,  rewrite_body(body));
                out = _lia_cat(out ,  "}\n");
              }
               else {
                zig_params = "";
                k = 0;
                pn = _lia_len(params);
                seen = 0;
                while (k < pn) {
                  k = skip_ws(params, k);
                  if (k >= pn) { break ;}
                  id = read_ident(params, k);
                  if (_lia_len(id) > 0) {
                    if (seen == 1) { zig_params = _lia_cat(zig_params ,  ", ") ;}
                    zig_params = _lia_cat(zig_params ,  id);
                    zig_params = _lia_cat(zig_params ,  ": ");
                    zig_params = _lia_cat(zig_params ,  param_zig_type(params, k + _lia_len(id)));
                    seen = 1;
                    k = skip_type(params, k + _lia_len(id));
                  }
                   else { k = k + 1 ;}
                  while (k < pn  and  _lia_char_code_at(params, k) != 44) { k = k + 1 ;}
                  if (k < pn  and  _lia_char_code_at(params, k) == 44) { k = k + 1 ;}
                }
                out = _lia_cat(out ,  "pub fn ");
                out = _lia_cat(out ,  name);
                out = _lia_cat(out ,  "(");
                out = _lia_cat(out ,  zig_params);
                out = _lia_cat(out ,  ") ");
                out = _lia_cat(out ,  fn_ret_type(src, close_p + 1, b));
                out = _lia_cat(out ,  " {\n");
                out = _lia_cat(out ,  zig_decls(body, js_p));
                out = _lia_cat(out ,  zig_pipe(body));
                out = _lia_cat(out ,  "\n}\n\n");
              }
              i = close_b + 1;
              continue;
            }
          }
        }
      }
    }
    i = i + 1;
  }
  return out;

}

pub fn lin_to_js(src: []const u8) []const u8 {
 return emit_fns(src, 0) ;
}

pub fn lin_to_zig(src: []const u8) []const u8 {
 return emit_fns(src, 1) ;
}

pub fn rewrite_inc(inc: []const u8) []const u8 {
    var out: []const u8 = "";
    var k: i64 = 0;
    var id: []const u8 = "";
    var p: i64 = 0;

  out = "";
  k = skip_ws(inc, 0);
  id = read_ident(inc, k);
  if (_lia_len(id) == 0) { return inc ;}
  p = skip_ws(inc, k + _lia_len(id));
  if (p + 1 < _lia_len(inc)  and  _lia_char_code_at(inc, p) == 43  and  _lia_char_code_at(inc, p + 1) == 43) {
    out = id;
    out = _lia_cat(out ,  " = ");
    out = _lia_cat(out ,  id);
    out = _lia_cat(out ,  " + 1");
    return out;
  }
  return inc;

}

pub fn rewrite_cfor(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var cl: i64 = 0;
    var b: i64 = 0;
    var cb: i64 = 0;
    var inner: []const u8 = "";
    var s1: i64 = 0;
    var s2: i64 = 0;
    var k: i64 = 0;

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  cl = 0;
  b = 0;
  cb = 0;
  inner = "";
  s1 = 0;
  s2 = 0;
  k = 0;
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
      continue;
    }
    if (_lia_char_code_at(s, i) == 35  and  i + 1 < n  and  _lia_char_code_at(s, i + 1) == 40) {
      cl = match_paren(s, i + 1);
      if (cl > i + 1) {
        b = find_brace(s, cl + 1);
        if (b >= 0) {
          cb = match_brace(s, b);
          if (cb > b) {
            inner = slice2(s, i + 2, cl);
            s1 = -1;
            s2 = -1;
            k = 0;
            while (k < _lia_len(inner)) {
              if (_lia_char_code_at(inner, k) == 59) {
                if (s1 < 0) { s1 = k ;}
                 else { s2 = k ;}
              }
              k = k + 1;
            }
            if (s1 >= 0  and  s2 > s1) {
              out = _lia_cat(out ,  slice2(inner, 0, s1));
              out = _lia_cat(out ,  ";");
              out = _lia_cat(out ,  "while");
              out = _lia_cat(out ,  "(");
              out = _lia_cat(out ,  slice2(inner, s1 + 1, s2));
              out = _lia_cat(out ,  ")");
              out = _lia_cat(out ,  "{");
              out = _lia_cat(out ,  slice2(s, b + 1, cb));
              out = _lia_cat(out ,  ";");
              out = _lia_cat(out ,  rewrite_inc(slice2(inner, s2 + 1, _lia_len(inner))));
              out = _lia_cat(out ,  ";");
              out = _lia_cat(out ,  "}");
              i = cb + 1;
              continue;
            }
          }
        }
      }
    }
    chs = _lia_char_at(s, i);
    out = _lia_cat(out ,  chs);
    i = i + 1;
  }
  return out;

}

pub fn rewrite_match(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var chs: []const u8 = "";
    var i: i64 = 0;
    var n: i64 = 0;
    var cl: i64 = 0;
