    var j: i64 = 0;
    var ab: i64 = 0;
    var arm: []const u8 = "";

  out = "";
  chs = "";
  i = 0;
  n = _lia_len(s);
  cl = 0;
  b = 0;
  cb = 0;
  expr = "";
  inner = "";
  p = 0;
  first = 0;
  pat = "";
  j = 0;
  ab = 0;
  arm = "";
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  q());
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) {
        chs = _lia_char_at(s, i);
        out = _lia_cat(out ,  chs);
        i = i + 1;
      }
      if (i < n) { out = _lia_cat(out ,  q()); i = i + 1 ;}
