  t = 0;
  c = 0;
  while (i < n) {
    c = _lia_char_code_at(s, i);
    if (c == 40  or  c == 91) { d = d + 1; i = i + 1; continue ;}
    if (c == 41  or  c == 93) { d = d - 1; i = i + 1; continue ;}
    if (d == 0  and  c == 63) { t = t + 1 ;}
    if (d == 0  and  c == 58) {
      if (t == 0) { return i ;}
      t = t - 1;
    }
    i = i + 1;
  }
  return -1;

}

