pub fn jss_u32_dec(v: i64) []const u8 {
    var neg: []const u8 = "";
    var x: i64 = 0;
    var out: []const u8 = "";
    var d: i64 = 0;

  if (v == 0) { return "0" ;}
  if (v == -9223372036854775808) { return "-9223372036854775808" ;}
  neg = "";
  x = v;
  if (x < 0) { neg = "-"; x = 0 - x ;}
  out = "";
  d = 0;
  while (x > 0) {
    d = rg_rem(x, 10);
    out = jss_cons_ch(48 + d, out);
    x = rg_digit(x, 10);
  }
  return _lia_cat(neg ,  out);

}

pub fn jss_rewrite_hex(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var c: i64 = 0;
    var d: i64 = 0;
    var v: i64 = 0;
    var prev: i64 = 0;

  out = "";
  n = _lia_len(s);
  i = 0;
  c = 0;
  d = 0;
  v = 0;
  prev = 0;
  while (i < n) {
    c = _lia_char_code_at(s, i);
    if (c == 34  or  c == 39) {
      out = _lia_cat(out ,  _lia_char_at(s, i));
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != c) { out = _lia_cat(out ,  _lia_char_at(s, i)); i = i + 1 ;}
      if (i < n) { out = _lia_cat(out ,  _lia_char_at(s, i)); i = i + 1 ;}
      continue;
    }
    if (c == 48  and  i + 1 < n  and  (_lia_char_code_at(s, i + 1) == 120  or  _lia_char_code_at(s, i + 1) == 88)) {
      prev = 0;
      if (i > 0) { prev = _lia_char_code_at(s, i - 1) ;}
      if (is_ident(prev) == false) {
        i = i + 2;
        v = 0;
        d = -1;
        if (i < n) { d = jss_hex_digit(_lia_char_code_at(s, i)) ;}
        while (i < n  and  d >= 0) {
          v = v * 16 + d;
          i = i + 1;
          if (i < n) { d = jss_hex_digit(_lia_char_code_at(s, i)) ;}  else { d = -1 ;}
        }
        out = _lia_cat(out ,  jss_u32_dec(v));
        continue;
      }
    }
    out = _lia_cat(out ,  _lia_char_at(s, i));
    i = i + 1;
  }
  return out;

}

pub fn jss_e12(s: []const u8) []const u8 {
    var e: []const u8 = "";
    var n: i64 = 0;
    var cl: i64 = 0;
    var id: []const u8 = "";
    var out: []const u8 = "";
    var p: i64 = 0;

  e = jss_trim(s);
  n = _lia_len(e);
  if (n == 0) { return "0" ;}
  cl = 0;
  if (_lia_char_code_at(e, 0) == 40) {
    cl = match_paren(e, 0);
    if (cl == n - 1) { return jss_e0(slice2(e, 1, cl)) ;}
  }
  id = read_ident(e, 0);
  out = "";
  if (_lia_len(id) > 0) {
    p = skip_ws(e, _lia_len(id));
    if (p < n  and  _lia_char_code_at(e, p) == 40) {
      cl = match_paren(e, p);
      if (cl == n - 1) {
        out = _lia_cat(out ,  id);
        out = _lia_cat(out ,  "(");
        out = _lia_cat(out ,  jss_args(slice2(e, p + 1, cl)));
        out = _lia_cat(out ,  ")");
        return out;
      }
    }
    if (p < n  and  _lia_char_code_at(e, p) == 91) {
      cl = match_brack(e, p);
      if (cl == n - 1) {
        out = _lia_cat(out ,  id);
        out = _lia_cat(out ,  "[");
        out = _lia_cat(out ,  jss_e0(slice2(e, p + 1, cl)));
        out = _lia_cat(out ,  "]");
        return out;
      }
    }
  }
  out = _lia_cat(out ,  e);
  return out;

}

