      while (i < n  and  _lia_char_code_at(s, i) != c) { out = _lia_cat(out ,  _lia_char_at(s, i)); i = i + 1 ;}
      if (i < n) { out = _lia_cat(out ,  _lia_char_at(s, i)); i = i + 1 ;}
      continue;
    }
    if (c == 47  and  i + 1 < n  and  _lia_char_code_at(s, i + 1) == 47) {
      while (i < n  and  _lia_char_code_at(s, i) != 10) { i = i + 1 ;}
      continue;
    }
    if (c == 47  and  i + 1 < n  and  _lia_char_code_at(s, i + 1) == 42) {
      i = i + 2;
      while (i + 1 < n  and  (_lia_char_code_at(s, i) != 42  or  _lia_char_code_at(s, i + 1) != 47)) { i = i + 1 ;}
      i = i + 2;
      continue;
    }
    out = _lia_cat(out ,  _lia_char_at(s, i));
    i = i + 1;
  }
  return out;

}

pub fn jss_replace_word(s: []const u8, w: []const u8, v: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var wl: i64 = 0;
    var i: i64 = 0;
    var keep: i64 = 0;

  out = "";
  n = _lia_len(s);
  wl = _lia_len(w);
  i = 0;
  keep = 0;
  while (i < n) {
    if (starts_lit(s, i, w) == 1) {
      keep = 1;
      if (i > 0  and  is_ident(_lia_char_code_at(s, i - 1)) == true) { keep = 0 ;}
      if (i + wl < n  and  is_ident(_lia_char_code_at(s, i + wl)) == true) { keep = 0 ;}
      if (keep == 1) {
        out = _lia_cat(out ,  v);
        i = i + wl;
        continue;
      }
    }
    out = _lia_cat(out ,  _lia_char_at(s, i));
    i = i + 1;
  }
  return out;

}

pub fn jss_one_const(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var p: i64 = 0;
    var e: i64 = 0;
    var ds: i64 = 0;
    var nm: []const u8 = "";

  out = "";
  n = _lia_len(s);
  i = 0;
  p = 0;
  e = 0;
  ds = 0;
  nm = "";
  while (i < n) {
    if (starts_lit(s, i, "var") == 1  and  i + 3 < n  and  is_ident(_lia_char_code_at(s, i + 3)) == false) {
      p = skip_ws(s, i + 3);
      nm = read_ident(s, p);
