        p = skip_ws(s, p + _lia_len(nm));
        if (p < n  and  _lia_char_code_at(s, p) == 61  and  (p + 1 >= n  or  _lia_char_code_at(s, p + 1) != 61)) {
          ds = skip_ws(s, p + 1);
          e = ds;
          while (e < n  and  _lia_char_code_at(s, e) >= 48  and  _lia_char_code_at(s, e) <= 57) { e = e + 1 ;}
          if (e > ds) {
            p = skip_ws(s, e);
            if (p < n  and  _lia_char_code_at(s, p) == 59) {
              return jss_replace_word(s, nm, slice2(s, ds, e));
