  out = _lia_cat(out ,  jss_e0(rhs));
  out = _lia_cat(out ,  ")");
  return out;

}

pub fn jss_step(id: []const u8, ops: []const u8) []const u8 {
    var out: []const u8 = "";

  out = "";
  out = _lia_cat(out ,  id);
  out = _lia_cat(out ,  " = ");
  out = _lia_cat(out ,  id);
  out = _lia_cat(out ,  " ");
  out = _lia_cat(out ,  ops);
  out = _lia_cat(out ,  " 1");
  return out;

}

pub fn jss_vardecl(rest: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var st: i64 = 0;
    var d: i64 = 0;
    var c: i64 = 0;
    var first: i64 = 0;
    var seg: []const u8 = "";

  out = "";
  n = _lia_len(rest);
  i = 0;
  st = 0;
  d = 0;
  c = 0;
  first = 1;
  seg = "";
  while (i <= n) {
    if (i == n  or  (d == 0  and  _lia_char_code_at(rest, i) == 44)) {
      seg = jss_trim(slice2(rest, st, i));
      if (_lia_len(seg) > 0) {
        if (first == 0) { out = _lia_cat(out ,  "; ") ;}
        out = _lia_cat(out ,  jss_one_var(seg));
        first = 0;
      }
      st = i + 1;
      i = i + 1;
      continue;
    }
    c = _lia_char_code_at(rest, i);
    if (c == 40) { d = d + 1 ;}
    if (c == 41) { d = d - 1 ;}
    i = i + 1;
  }
  return out;

}

pub fn jss_one_var(seg: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var nm: []const u8 = "";
    var p: i64 = 0;

  out = "";
  n = _lia_len(seg);
  nm = read_ident(seg, 0);
  if (_lia_len(nm) == 0) { return out ;}
  p = skip_ws(seg, _lia_len(nm));
  if (p < n  and  _lia_char_code_at(seg, p) == 61) {
    out = _lia_cat(out ,  nm);
    out = _lia_cat(out ,  " = ");
    out = _lia_cat(out ,  jss_e0(slice2(seg, p + 1, n)));
    return out;
  }
  out = _lia_cat(out ,  nm);
  out = _lia_cat(out ,  " = 0");
  return out;

}

pub fn jss_stmt(st: []const u8) []const u8 {
    var e: []const u8 = "";
    var n: i64 = 0;
    var out: []const u8 = "";
    var p: i64 = 0;
    var cl: i64 = 0;
    var id: []const u8 = "";
    var qpos: i64 = 0;

  e = jss_trim(st);
  n = _lia_len(e);
  out = "";
  if (n == 0) { return out ;}
  p = 0;
  cl = 0;
  id = "";
  if (starts_lit(e, 0, "if") == 1  and  n > 2  and  is_ident(_lia_char_code_at(e, 2)) == false) {
    p = skip_ws(e, 2);
    if (p < n  and  _lia_char_code_at(e, p) == 40) {
      cl = match_paren(e, p);
      if (cl > p) {
        out = _lia_cat(out ,  "?(");
        out = _lia_cat(out ,  jss_e0(slice2(e, p + 1, cl)));
        out = _lia_cat(out ,  " != 0){ ");
        out = _lia_cat(out ,  jss_stmt(slice2(e, cl + 1, n)));
        out = _lia_cat(out ,  " }");
        return out;
      }
    }
  }
  if (starts_lit(e, 0, "return") == 1  and  (n == 6  or  is_ident(_lia_char_code_at(e, 6)) == false)) {
    out = _lia_cat(out ,  "^");
    out = _lia_cat(out ,  jss_e0(slice2(e, 6, n)));
    return out;
  }
  if (starts_lit(e, 0, "var") == 1  and  n > 3  and  is_ident(_lia_char_code_at(e, 3)) == false) {
    return jss_vardecl(slice2(e, 3, n));
  }
  if (starts_lit(e, 0, "++") == 1) { return jss_step(read_ident(e, skip_ws(e, 2)), "+") ;}
  if (starts_lit(e, 0, "--") == 1) { return jss_step(read_ident(e, skip_ws(e, 2)), "-") ;}
  id = read_ident(e, 0);
  if (_lia_len(id) > 0) {
    p = skip_ws(e, _lia_len(id));
    if (starts_lit(e, p, "++") == 1) { return jss_step(id, "+") ;}
    if (starts_lit(e, p, "--") == 1) { return jss_step(id, "-") ;}
    if (starts_lit(e, p, ">>>=") == 1) { return jss_comp(id, "js_ushr", slice2(e, p + 4, n)) ;}
    if (starts_lit(e, p, "<<=") == 1) { return jss_comp(id, "js_shl", slice2(e, p + 3, n)) ;}
    if (starts_lit(e, p, ">>=") == 1) { return jss_comp(id, "js_shr", slice2(e, p + 3, n)) ;}
    if (starts_lit(e, p, "|=") == 1) { return jss_comp(id, "js_or", slice2(e, p + 2, n)) ;}
    if (starts_lit(e, p, "&=") == 1) { return jss_comp(id, "js_and", slice2(e, p + 2, n)) ;}
    if (starts_lit(e, p, "^=") == 1) { return jss_comp(id, "js_xor", slice2(e, p + 2, n)) ;}
    if (starts_lit(e, p, "+=") == 1) { return jss_compn(id, "+", slice2(e, p + 2, n)) ;}
    if (starts_lit(e, p, "-=") == 1) { return jss_compn(id, "-", slice2(e, p + 2, n)) ;}
    if (starts_lit(e, p, "*=") == 1) { return jss_compn(id, "*", slice2(e, p + 2, n)) ;}
    if (p < n  and  _lia_char_code_at(e, p) == 91) {
      cl = match_brack(e, p);
      if (cl > p) {
        qpos = skip_ws(e, cl + 1);
        if (qpos < n  and  _lia_char_code_at(e, qpos) == 61  and  (qpos + 1 >= n  or  _lia_char_code_at(e, qpos + 1) != 61)) {
          out = _lia_cat(out ,  id);
          out = _lia_cat(out ,  "[");
          out = _lia_cat(out ,  jss_e0(slice2(e, p + 1, cl)));
          out = _lia_cat(out ,  "] = ");
          out = _lia_cat(out ,  jss_e0(slice2(e, qpos + 1, n)));
          return out;
        }
      }
    }
    if (p < n  and  _lia_char_code_at(e, p) == 61  and  (p + 1 >= n  or  _lia_char_code_at(e, p + 1) != 61)) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  jss_e0(slice2(e, p + 1, n)));
      return out;
    }
  }
  out = _lia_cat(out ,  "JS_UNSUPPORTED");
  return out;

}

pub fn jss_body(b: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var st: i64 = 0;
    var d: i64 = 0;
    var c: i64 = 0;
    var seg: []const u8 = "";
    var conv: []const u8 = "";

  out = "";
  n = _lia_len(b);
  i = 0;
  st = 0;
  d = 0;
  c = 0;
  seg = "";
  conv = "";
  while (i <= n) {
    if (i == n  or  (d == 0  and  _lia_char_code_at(b, i) == 59)) {
      seg = jss_trim(slice2(b, st, i));
      if (_lia_len(seg) > 0) {
        conv = jss_stmt(seg);
        if (_lia_len(conv) > 0) {
          out = _lia_cat(out ,  "  ");
          out = _lia_cat(out ,  conv);
          out = _lia_cat(out ,  ";");
          out = _lia_cat(out ,  rgs_ch(10));
        }
      }
      st = i + 1;
      i = i + 1;
      continue;
    }
    c = _lia_char_code_at(b, i);
    if (c == 40  or  c == 123  or  c == 91) { d = d + 1 ;}
    if (c == 41  or  c == 125  or  c == 93) { d = d - 1 ;}
    i = i + 1;
  }
  return out;

}

pub fn jss_pcsv(p: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var st: i64 = 0;
    var seg: []const u8 = "";

  out = "";
  n = _lia_len(p);
  i = 0;
  st = 0;
  seg = "";
  while (i <= n) {
    if (i == n  or  _lia_char_code_at(p, i) == 44) {
      seg = jss_trim(slice2(p, st, i));
      if (_lia_len(seg) > 0) { out = rgs_csv_add(out, seg) ;}
      st = i + 1;
      i = i + 1;
      continue;
    }
    i = i + 1;
  }
  return out;

}

pub fn jss_pdecl(pcsv: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var k: i64 = 0;
    var e: i64 = 0;
    var idx: i64 = 0;

  out = "";
  n = _lia_len(pcsv);
  k = 0;
  e = 0;
  idx = 0;
  while (k < n) {
    e = rg_csv_end(pcsv, k);
    if (idx > 0) { out = _lia_cat(out ,  ", ") ;}
    out = _lia_cat(out ,  "a");
    out = _lia_cat(out ,  rgs_num(idx));
    out = _lia_cat(out ,  ": int");
    idx = idx + 1;
    k = e + 1;
  }
  return out;

}

pub fn jss_palias(pcsv: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var k: i64 = 0;
    var e: i64 = 0;
    var idx: i64 = 0;

  out = "";
  n = _lia_len(pcsv);
  k = 0;
  e = 0;
  idx = 0;
  while (k < n) {
    e = rg_csv_end(pcsv, k);
    out = _lia_cat(out ,  "  ");
    out = _lia_cat(out ,  slice2(pcsv, k, e));
    out = _lia_cat(out ,  " = a");
    out = _lia_cat(out ,  rgs_num(idx));
    out = _lia_cat(out ,  ";");
    out = _lia_cat(out ,  rgs_ch(10));
    idx = idx + 1;
    k = e + 1;
  }
  return out;

}

pub fn jsf_eligible_reason(pcsv: []const u8, body: []const u8, known: []const u8) []const u8 {
    var br: []const u8 = "";
    var reads: []const u8 = "";
    var calls: []const u8 = "";

  br = jss_trim(jsf_brackets_ok(body));
  if (starts_lit(br, 0, "OK") == 0  or  _lia_len(br) != 2) { return br ;}
  if (rg_count_lit(body, ".") > 0) { return "REJ_MEMBER_DOT" ;}
  if (rg_count_lit(body, "=>") > 0) { return "REJ_ARROW_FN" ;}
  if (rg_count_lit(body, "new ") > 0) { return "REJ_NEW_CLASS" ;}
  if (rg_count_lit(body, "function") > 0) { return "REJ_FUNCTION_KEYWORD" ;}
  if (rg_count_lit(body, "{") > 0) { return "REJ_OBJ_LITERAL" ;}
  reads = rgs_csv_minus(rgs_scan(body, 1), rgs_scan(body, 2));
  reads = rgs_csv_minus(reads, pcsv);
  reads = rgs_csv_minus(reads, "var,return,if,else,true,false,null,undefined");
  if (rg_count_lit(body, "REVERSE_TABLE") > 0) { reads = rgs_csv_minus(reads, "REVERSE_TABLE") ;}
  if (_lia_len(reads) > 0) { return "REJ_UNKNOWN_IDENT" ;}
  calls = rgs_csv_minus(rgs_scan(body, 3), known);
  if (_lia_len(calls) > 0) { return "REJ_UNKNOWN_CALL" ;}
  return "OK";

}

pub fn jsf_eligible(pcsv: []const u8, body: []const u8, known: []const u8) i64 {
    var r: []const u8 = "";

  r = jss_trim(jsf_eligible_reason(pcsv, body, known));
  if (starts_lit(r, 0, "OK") == 1  and  _lia_len(r) == 2) { return 1 ;}
  return 0;

}

pub fn jss_fn(nm: []const u8, params: []const u8, body: []const u8) []const u8 {
    var out: []const u8 = "";
    var pcsv: []const u8 = "";

  out = "";
  pcsv = jss_pcsv(params);
  out = _lia_cat(out ,  "!");
  out = _lia_cat(out ,  nm);
  out = _lia_cat(out ,  "(");
  out = _lia_cat(out ,  jss_pdecl(pcsv));
  out = _lia_cat(out ,  "): int {");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  jss_palias(pcsv));
  if (rg_count_lit(body, "REVERSE_TABLE") > 0) { out = _lia_cat(out ,  jss_rev256_assign()) ;}
  out = _lia_cat(out ,  jss_body(body));
  out = _lia_cat(out ,  "}");
  out = _lia_cat(out ,  rgs_ch(10));
  return out;

}

pub fn jss_prelude() []const u8 {
    var out: []const u8 = "";

  out = "";
  out = jss_ln(out, "!js_i32(x: int): int {");
  out = jss_ln(out, "  m = x & 4294967295;");
  out = jss_ln(out, "  ?(m >= 2147483648){ ^m - 4294967296 };");
  out = jss_ln(out, "  ^m;");
  out = jss_ln(out, "}");
  out = jss_ln(out, "");
  out = jss_ln(out, "!js_u32(x: int): int { ^x & 4294967295 }");
  out = jss_ln(out, "!js_and(a: int, b: int): int { ^js_i32(a) & js_i32(b) }");
  out = jss_ln(out, "!js_or(a: int, b: int): int { ^js_i32(a) | js_i32(b) }");
  out = jss_ln(out, "!js_bnot(a: int): int { ^js_i32(~js_i32(a)) }");
  out = jss_ln(out, "!js_neg(a: int): int { ^0 - a }");
  out = jss_ln(out, "");
  out = jss_ln(out, "!js_xor(a: int, b: int): int {");
  out = jss_ln(out, "  x = js_i32(a);");
  out = jss_ln(out, "  y = js_i32(b);");
  out = jss_ln(out, "  ^(x | y) & ~(x & y);");
  out = jss_ln(out, "}");
  out = jss_ln(out, "");
  out = jss_ln(out, "!js_shl(a: int, b: int): int { ^js_i32(_lia_shl(js_i32(a), b & 31)) }");
  out = jss_ln(out, "!js_shr(a: int, b: int): int { ^_lia_shr(js_i32(a), b & 31) }");
  out = jss_ln(out, "!js_ushr(a: int, b: int): int { ^_lia_shr(js_u32(a), b & 31) }");
  out = jss_ln(out, "");
  out = jss_ln(out, "!js_lt(a: int, b: int): int { ?(a < b){ ^1 }; ^0 }");
  out = jss_ln(out, "!js_gt(a: int, b: int): int { ?(a > b){ ^1 }; ^0 }");
  out = jss_ln(out, "!js_le(a: int, b: int): int { ?(a <= b){ ^1 }; ^0 }");
  out = jss_ln(out, "!js_ge(a: int, b: int): int { ?(a >= b){ ^1 }; ^0 }");
  out = jss_ln(out, "!js_eq(a: int, b: int): int { ?(a == b){ ^1 }; ^0 }");
  out = jss_ln(out, "!js_ne(a: int, b: int): int { ?(a != b){ ^1 }; ^0 }");
  out = jss_ln(out, "!js_lnot(a: int): int { ?(a == 0){ ^1 }; ^0 }");
  out = jss_ln(out, "!js_land(a: int, b: int): int { ?(a == 0){ ^0 }; ^b }");
  out = jss_ln(out, "!js_lor(a: int, b: int): int { ?(a != 0){ ^a }; ^b }");
  out = jss_ln(out, "!js_sel(c: int, a: int, b: int): int { ?(c != 0){ ^a }; ^b }");
  out = jss_ln(out, "");
  return out;

}

pub fn jss_helpers_csv() []const u8 {

  return "js_i32,js_u32,js_and,js_or,js_bnot,js_neg,js_xor,js_shl,js_shr,js_ushr,js_lt,js_gt,js_le,js_ge,js_eq,js_ne,js_lnot,js_land,js_lor,js_sel";

}

pub fn jsd_paren_at(s: []const u8, i: i64) i64 {
    var n: i64 = 0;
    var p: i64 = 0;
    var nm: []const u8 = "";

  n = _lia_len(s);
  p = 0;
  nm = "";
  if (starts_lit(s, i, "exports.") == 1) {
    nm = read_ident(s, i + 8);
    if (_lia_len(nm) == 0) { return -1 ;}
    p = skip_ws(s, i + 8 + _lia_len(nm));
    if (p >= n  or  _lia_char_code_at(s, p) != 61) { return -1 ;}
    p = skip_ws(s, p + 1);
    if (starts_lit(s, p, "function") == 1) {
      p = skip_ws(s, p + 8);
      if (p < n  and  _lia_char_code_at(s, p) == 40) { return p ;}
    }
    return -1;
  }
  if (starts_lit(s, i, "function") == 1  and  (i == 0  or  is_ident(_lia_char_code_at(s, i - 1)) == false)) {
    p = skip_ws(s, i + 8);
    nm = read_ident(s, p);
    if (_lia_len(nm) > 0) {
      p = skip_ws(s, p + _lia_len(nm));
      if (p < n  and  _lia_char_code_at(s, p) == 40) { return p ;}
    }
  }
  return -1;

}

pub fn jsd_fn_at(s: []const u8, i: i64) i64 {

  return jsd_paren_at(s, i);

}

pub fn jsd_name_at(s: []const u8, i: i64) []const u8 {
    var p: i64 = 0;

  if (starts_lit(s, i, "exports.") == 1) { return read_ident(s, i + 8) ;}
  if (starts_lit(s, i, "function") == 1  and  (i == 0  or  is_ident(_lia_char_code_at(s, i - 1)) == false)) {
    p = skip_ws(s, i + 8);
    return read_ident(s, p);
  }
  return "";

}

pub fn jsd_names(src: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var fp: i64 = 0;
    var cl: i64 = 0;
    var b: i64 = 0;
    var cb: i64 = 0;
    var nm: []const u8 = "";

  out = "";
  n = _lia_len(src);
  i = 0;
  fp = 0;
  cl = 0;
  b = 0;
  cb = 0;
  nm = "";
  while (i < n) {
    fp = jsd_fn_at(src, i);
    if (fp >= 0) {
      nm = jsd_name_at(src, i);
      cl = match_paren(src, fp);
      if (cl > fp) {
        b = find_brace(src, cl + 1);
        if (b >= 0) {
          cb = match_brace(src, b);
          if (cb > b) {
            out = rgs_csv_add(out, nm);
            i = b + 1;
            continue;
          }
        }
      }
    }
    i = i + 1;
  }
  return out;

}

pub fn jsd_fns(src: []const u8, known: []const u8, want: i64) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var fp: i64 = 0;
    var cl: i64 = 0;
    var b: i64 = 0;
    var cb: i64 = 0;
    var nm: []const u8 = "";
    var pr: []const u8 = "";
    var bd: []const u8 = "";
    var pcsv: []const u8 = "";
    var gen: []const u8 = "";

  out = "";
  n = _lia_len(src);
  i = 0;
  fp = 0;
  cl = 0;
  b = 0;
  cb = 0;
  nm = "";
  pr = "";
  bd = "";
  pcsv = "";
  gen = "";
  while (i < n) {
    fp = jsd_fn_at(src, i);
    if (fp >= 0) {
      nm = jsd_name_at(src, i);
      cl = match_paren(src, fp);
      if (cl > fp) {
        b = find_brace(src, cl + 1);
        if (b >= 0) {
          cb = match_brace(src, b);
          if (cb > b) {
            pr = slice2(src, fp + 1, cl);
            bd = slice2(src, b + 1, cb);
            pcsv = jss_pcsv(pr);
            if (jsf_eligible(pcsv, bd, known) == 1) {
              gen = jss_fn(nm, pr, bd);
              if (rg_count_lit(gen, "JS_UNSUPPORTED") == 0) {
                if (want == 1) { out = _lia_cat(out ,  gen) ;}
                 else { out = rgs_csv_add(out, nm) ;}
              }
            }
            i = b + 1;
            continue;
          }
        }
      }
    }
    i = i + 1;
  }
  return out;

}

pub fn jsd_ncsv(s: []const u8) i64 {

  if (_lia_len(s) == 0) { return 0 ;}
  return rg_count_lit(s, ",") + 1;

}

pub fn jsd_prep(src: []const u8) []const u8 {
    var clean: []const u8 = "";
    var pass: []const u8 = "";
    var k: i64 = 0;

  clean = jss_strip_comments(src);
  pass = jss_rewrite_hex(clean);
  k = 0;
  while (k < 8) {
    pass = jss_one_const(pass);
    k = k + 1;
  }
  return pass;

}

pub fn jss_from_js(src: []const u8) []const u8 {
    var out: []const u8 = "";
    var pass: []const u8 = "";
    var known: []const u8 = "";
    var jss_emitted: []const u8 = "";
    var jss_oknames: []const u8 = "";

  out = "";
  pass = jsd_prep(src);
  known = rgs_csv_merge(jss_helpers_csv(), jsd_names(pass));
  jss_emitted = jsd_fns(pass, known, 1);
  jss_oknames = jsd_fns(pass, known, 0);
  out = jss_ln(out, "@LIN:L1c:0.2");
  out = jss_ln(out, "@FROM_JS{source=transpiled scope=pure_scalar_int_functions semantics=js_int32}");
  out = jss_ln(out, "");
  out = _lia_cat(out ,  jss_prelude());
  out = _lia_cat(out ,  jss_emitted);
  out = _lia_cat(out ,  "=ex{");
  out = _lia_cat(out ,  rgs_csv_merge(jss_helpers_csv(), jss_oknames));
  out = _lia_cat(out ,  "}");
  out = _lia_cat(out ,  rgs_ch(10));
  return out;

}

pub fn jsd_gap(src: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var fp: i64 = 0;
    var cl: i64 = 0;
    var b: i64 = 0;
    var cb: i64 = 0;
    var nm: []const u8 = "";
    var pr: []const u8 = "";
    var bd: []const u8 = "";
    var pcsv: []const u8 = "";
    var reason: []const u8 = "";
    var gen: []const u8 = "";
    var known: []const u8 = "";

  out = "";
  n = _lia_len(src);
  i = 0;
  fp = 0;
  cl = 0;
  b = 0;
  cb = 0;
  nm = "";
  pr = "";
  bd = "";
  pcsv = "";
  reason = "";
  gen = "";
  known = rgs_csv_merge(jss_helpers_csv(), jsd_names(src));
  while (i < n) {
    fp = jsd_fn_at(src, i);
    if (fp >= 0) {
      nm = jsd_name_at(src, i);
      cl = match_paren(src, fp);
      if (cl > fp) {
        b = find_brace(src, cl + 1);
        if (b >= 0) {
          cb = match_brace(src, b);
          if (cb > b) {
            pr = slice2(src, fp + 1, cl);
            bd = slice2(src, b + 1, cb);
            pcsv = jss_pcsv(pr);
            reason = jsf_eligible_reason(pcsv, bd, known);
            if (starts_lit(reason, 0, "OK") == 1  and  _lia_len(reason) == 2) {
              gen = jss_fn(nm, pr, bd);
              if (rg_count_lit(gen, "JS_UNSUPPORTED") > 0) { reason = "REJ_STMT_UNSUPPORTED" ;}
            }
            out = _lia_cat(out ,  "  .fn{ name=");
            out = _lia_cat(out ,  q());
            out = _lia_cat(out ,  nm);
            out = _lia_cat(out ,  q());
            out = _lia_cat(out ,  " reason=");
            out = _lia_cat(out ,  reason);
            out = _lia_cat(out ,  " }");
            out = _lia_cat(out ,  rgs_ch(10));
            i = b + 1;
            continue;
          }
        }
      }
    }
    i = i + 1;
  }
  return out;

}

pub fn jss_report(src: []const u8) []const u8 {
    var out: []const u8 = "";
    var pass: []const u8 = "";
    var known: []const u8 = "";
    var jss_oknames: []const u8 = "";

  out = "";
  pass = jsd_prep(src);
  known = rgs_csv_merge(jss_helpers_csv(), jsd_names(pass));
  jss_oknames = jsd_fns(pass, known, 0);
  out = jss_ln(out, "@RULEL:LIN_FROM_JS:1.0.0");
  out = _lia_cat(out ,  ".found=");
  out = _lia_cat(out ,  rgs_num(jsd_ncsv(jsd_names(pass))));
  out = _lia_cat(out ,  " .eligible=");
  out = _lia_cat(out ,  rgs_num(jsd_ncsv(jss_oknames)));
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  ".names=");
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  jss_oknames);
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  rgs_ch(10));
  out = jss_ln(out, ".fns{");
  out = _lia_cat(out ,  jsd_gap(pass));
  out = jss_ln(out, "}");
  return out;

}

pub fn cfs_kw(nm: []const u8) i64 {

  if (starts_lit(nm, 0, "if") == 1  and  _lia_len(nm) == 2) { return 1 ;}
  if (starts_lit(nm, 0, "while") == 1  and  _lia_len(nm) == 5) { return 1 ;}
  if (starts_lit(nm, 0, "for") == 1  and  _lia_len(nm) == 3) { return 1 ;}
  if (starts_lit(nm, 0, "switch") == 1  and  _lia_len(nm) == 6) { return 1 ;}
  if (starts_lit(nm, 0, "sizeof") == 1  and  _lia_len(nm) == 6) { return 1 ;}
  if (starts_lit(nm, 0, "return") == 1  and  _lia_len(nm) == 6) { return 1 ;}
  return 0;

}

pub fn cfs_is_type(nm: []const u8) i64 {

  if (starts_lit(nm, 0, "uint32_t") == 1  and  _lia_len(nm) == 8) { return 1 ;}
  if (starts_lit(nm, 0, "uint64_t") == 1  and  _lia_len(nm) == 8) { return 1 ;}
  if (starts_lit(nm, 0, "int32_t") == 1  and  _lia_len(nm) == 7) { return 1 ;}
  if (starts_lit(nm, 0, "int64_t") == 1  and  _lia_len(nm) == 7) { return 1 ;}
  if (starts_lit(nm, 0, "uint8_t") == 1  and  _lia_len(nm) == 7) { return 1 ;}
  if (starts_lit(nm, 0, "unsigned") == 1  and  _lia_len(nm) == 8) { return 1 ;}
  if (starts_lit(nm, 0, "signed") == 1  and  _lia_len(nm) == 6) { return 1 ;}
  if (starts_lit(nm, 0, "static") == 1  and  _lia_len(nm) == 6) { return 1 ;}
  if (starts_lit(nm, 0, "inline") == 1  and  _lia_len(nm) == 6) { return 1 ;}
  if (starts_lit(nm, 0, "const") == 1  and  _lia_len(nm) == 5) { return 1 ;}
  if (starts_lit(nm, 0, "int") == 1  and  _lia_len(nm) == 3) { return 1 ;}
  if (starts_lit(nm, 0, "long") == 1  and  _lia_len(nm) == 4) { return 1 ;}
  if (starts_lit(nm, 0, "short") == 1  and  _lia_len(nm) == 5) { return 1 ;}
  if (starts_lit(nm, 0, "void") == 1  and  _lia_len(nm) == 4) { return 1 ;}
  return 0;

}

pub fn cfs_reason(sig: []const u8, body: []const u8) []const u8 {

  if (rg_count_lit(sig, "*") > 0) { return "REJ_C_POINTER" ;}
  if (rg_count_lit(body, "->") > 0) { return "REJ_C_POINTER" ;}
  if (rg_count_lit(sig, "struct") > 0  or  rg_count_lit(body, "struct") > 0) { return "REJ_C_STRUCT" ;}
  if (rg_count_lit(sig, "union") > 0  or  rg_count_lit(body, "union") > 0) { return "REJ_C_UNION" ;}
  if (rg_count_lit(sig, "float") > 0  or  rg_count_lit(body, "float") > 0) { return "REJ_C_FLOAT" ;}
  if (rg_count_lit(sig, "double") > 0  or  rg_count_lit(body, "double") > 0) { return "REJ_C_FLOAT" ;}
  if (rg_count_lit(body, "goto") > 0) { return "REJ_C_GOTO" ;}
  return "OK";

}

pub fn cfs_atom_left(s: []const u8, at: i64) i64 {
    var k: i64 = 0;
    var d: i64 = 0;

  k = at - 1;
  while (k >= 0  and  (_lia_char_code_at(s, k) == 32  or  _lia_char_code_at(s, k) == 9)) { k = k - 1 ;}
  if (k < 0) { return 0 ;}
  if (_lia_char_code_at(s, k) == 41) {
    d = 1;
    k = k - 1;
    while (k >= 0  and  d > 0) {
      if (_lia_char_code_at(s, k) == 41) { d = d + 1 ;}
      if (_lia_char_code_at(s, k) == 40) { d = d - 1 ;}
      k = k - 1;
    }
    return (k + 1);
  }
  if (is_ident(_lia_char_code_at(s, k)) == true  or  (_lia_char_code_at(s, k) >= 48  and  _lia_char_code_at(s, k) <= 57)) {
    while (k > 0  and  (is_ident(_lia_char_code_at(s, k - 1)) == true  or  (_lia_char_code_at(s, k - 1) >= 48  and  _lia_char_code_at(s, k - 1) <= 57))) { k = k - 1 ;}
    return k;
  }
  return at;

}

pub fn cfs_atom_right(s: []const u8, at: i64) i64 {
    var n: i64 = 0;
    var k: i64 = 0;
    var cl: i64 = 0;
    var id: []const u8 = "";

  n = _lia_len(s);
  k = skip_ws(s, at);
  if (k >= n) { return n ;}
  if (_lia_char_code_at(s, k) == 40) {
    cl = match_paren(s, k);
    if (cl > k) { return (cl + 1) ;}
  }
  id = read_ident(s, k);
  if (_lia_len(id) > 0) { return (k + _lia_len(id)) ;}
  while (k < n  and  _lia_char_code_at(s, k) >= 48  and  _lia_char_code_at(s, k) <= 57) { k = k + 1 ;}
  return k;

}

pub fn cfs_find_shift(s: []const u8, op: []const u8) i64 {
    var n: i64 = 0;
    var m: i64 = 0;
    var i: i64 = 0;
    var c: i64 = 0;

  n = _lia_len(s);
  m = _lia_len(op);
  i = 0;
  c = 0;
  while (i < n) {
    c = _lia_char_code_at(s, i);
    if (c == 34) {
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) { i = i + 1 ;}
      if (i < n) { i = i + 1 ;}
      continue;
    }
    if (starts_lit(s, i, op) == 1  and  jsx_prev_value(s, i) == 1  and  (i + m >= n  or  _lia_char_code_at(s, i + m) != 61)) { return i ;}
    i = i + 1;
  }
  return -1;

}

pub fn cfs_one_shift(s: []const u8) []const u8 {
    var i: i64 = 0;
    var op: []const u8 = "";
    var fname: []const u8 = "";
    var L: i64 = 0;
    var R: i64 = 0;
    var out: []const u8 = "";

  i = cfs_find_shift(s, ">>");
  op = ">>";
  fname = "_lia_shr";
  if (i < 0) {
    i = cfs_find_shift(s, "<<");
    op = "<<";
    fname = "_lia_shl";
  }
  if (i < 0) { return s ;}
  L = cfs_atom_left(s, i);
  R = cfs_atom_right(s, i + 2);
  out = "";
  out = _lia_cat(out ,  slice2(s, 0, L));
  out = _lia_cat(out ,  fname);
  out = _lia_cat(out ,  "(");
  out = _lia_cat(out ,  slice2(s, L, i));
  out = _lia_cat(out ,  ", ");
  out = _lia_cat(out ,  slice2(s, i + 2, R));
  out = _lia_cat(out ,  ")");
  out = _lia_cat(out ,  slice2(s, R, _lia_len(s)));
  return out;

}

pub fn cfs_shifts(s: []const u8) []const u8 {
    var e: []const u8 = "";
    var k: i64 = 0;
    var nxt: []const u8 = "";

  e = jss_trim(s);
  k = 0;
  nxt = "";
  while (k < 32) {
    nxt = jss_trim(cfs_one_shift(e));
    if (_lia_len(nxt) == _lia_len(e)) { return e ;}
    e = nxt;
    k = k + 1;
  }
  return e;

}

pub fn cfs_all_type(s: []const u8) i64 {
    var n: i64 = 0;
    var i: i64 = 0;
    var id: []const u8 = "";
    var ws: i64 = 0;
    var c: i64 = 0;

  n = _lia_len(s);
  i = 0;
  id = "";
  ws = 0;
  while (i < n) {
    c = _lia_char_code_at(s, i);
    if (c == 32  or  c == 9  or  c == 10) { i = i + 1; ws = 1; continue ;}
    id = read_ident(s, i);
    if (_lia_len(id) > 0) {
      if (cfs_is_type(id) == 1) { i = i + _lia_len(id); continue ;}
      return 0;
    }
    return 0;
  }
  return 1;

}

pub fn cfs_strip_casts(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var cl: i64 = 0;
    var seg: []const u8 = "";

  out = "";
  n = _lia_len(s);
  i = 0;
  cl = 0;
  seg = "";
  while (i < n) {
    if (_lia_char_code_at(s, i) == 40) {
      cl = match_paren(s, i);
      if (cl > i) {
        seg = jss_trim(slice2(s, i + 1, cl));
        if (_lia_len(seg) > 0  and  cfs_all_type(seg) == 1) {
          i = cl + 1;
          continue;
        }
      }
    }
    out = _lia_cat(out ,  _lia_char_at(s, i));
    i = i + 1;
  }
  return out;

}

pub fn cfs_strip_types(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var id: []const u8 = "";

  out = "";
  n = _lia_len(s);
  i = 0;
  id = "";
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  _lia_char_at(s, i));
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) { out = _lia_cat(out ,  _lia_char_at(s, i)); i = i + 1 ;}
      if (i < n) { out = _lia_cat(out ,  _lia_char_at(s, i)); i = i + 1 ;}
      continue;
    }
    id = read_ident(s, i);
    if (_lia_len(id) > 0) {
      if (cfs_is_type(id) == 1) { i = i + _lia_len(id); i = skip_ws(s, i); continue ;}
      out = _lia_cat(out ,  id);
      i = i + _lia_len(id);
      continue;
    }
    out = _lia_cat(out ,  _lia_char_at(s, i));
    i = i + 1;
  }
  return out;

}

pub fn cfs_braces_to_arr(s: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var cl: i64 = 0;
    var k: i64 = 0;

  out = "";
  n = _lia_len(s);
  i = 0;
  cl = 0;
  k = 0;
  while (i < n) {
    if (_lia_char_code_at(s, i) == 34) {
      out = _lia_cat(out ,  _lia_char_at(s, i));
      i = i + 1;
      while (i < n  and  _lia_char_code_at(s, i) != 34) { out = _lia_cat(out ,  _lia_char_at(s, i)); i = i + 1 ;}
      if (i < n) { out = _lia_cat(out ,  _lia_char_at(s, i)); i = i + 1 ;}
      continue;
    }
    if (_lia_char_code_at(s, i) == 123) {
      k = i - 1;
      while (k >= 0  and  (_lia_char_code_at(s, k) == 32  or  _lia_char_code_at(s, k) == 9)) { k = k - 1 ;}
      if (k >= 0  and  _lia_char_code_at(s, k) == 61) {
        cl = match_brace(s, i);
        if (cl > i  and  jsf_int_elems(s, i + 1, cl) == 1) {
          out = _lia_cat(out ,  "[");
          out = _lia_cat(out ,  slice2(s, i + 1, cl));
          out = _lia_cat(out ,  "]");
          i = cl + 1;
          continue;
        }
      }
    }
    out = _lia_cat(out ,  _lia_char_at(s, i));
    i = i + 1;
  }
  return out;

}

pub fn cfs_find_semi(s: []const u8, start: i64) i64 {
    var n: i64 = 0;
    var k: i64 = 0;

  n = _lia_len(s);
  k = start;
  while (k < n) {
    if (_lia_char_code_at(s, k) == 59) { return k ;}
    k = k + 1;
  }
  return -1;

}

pub fn cfs_step_to_assign(s: []const u8) []const u8 {
    var t: []const u8 = "";
    var n: i64 = 0;
    var out: []const u8 = "";
    var id: []const u8 = "";
    var p: i64 = 0;

  t = jss_trim(s);
  n = _lia_len(t);
  out = "";
  if (starts_lit(t, 0, "++") == 1) {
    id = read_ident(t, skip_ws(t, 2));
    out = _lia_cat(out ,  id);
    out = _lia_cat(out ,  " = ");
    out = _lia_cat(out ,  id);
    out = _lia_cat(out ,  " + 1");
    return out;
  }
  if (starts_lit(t, 0, "--") == 1) {
    id = read_ident(t, skip_ws(t, 2));
    out = _lia_cat(out ,  id);
    out = _lia_cat(out ,  " = ");
    out = _lia_cat(out ,  id);
    out = _lia_cat(out ,  " - 1");
    return out;
  }
  id = read_ident(t, 0);
  if (_lia_len(id) > 0) {
    p = skip_ws(t, _lia_len(id));
    if (starts_lit(t, p, "++") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " + 1");
      return out;
    }
    if (starts_lit(t, p, "--") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " - 1");
      return out;
    }
    if (starts_lit(t, p, "+=") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " + (");
      out = _lia_cat(out ,  jss_trim(slice2(t, p + 2, n)));
      out = _lia_cat(out ,  ")");
      return out;
    }
    if (starts_lit(t, p, "-=") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " - (");
      out = _lia_cat(out ,  jss_trim(slice2(t, p + 2, n)));
      out = _lia_cat(out ,  ")");
      return out;
    }
  }
  return cfs_stmt(t);

}

pub fn cfs_brace_body(s: []const u8) []const u8 {
    var t: []const u8 = "";
    var n: i64 = 0;

  t = jss_trim(s);
  n = _lia_len(t);
  while (n >= 2  and  _lia_char_code_at(t, 0) == 123  and  _lia_char_code_at(t, n - 1) == 125) {
    t = jss_trim(slice2(t, 1, n - 1));
    n = _lia_len(t);
  }
  if (n == 0) { return "" ;}
  if (starts_lit(t, 0, "break") == 1  and  (n == 5  or  is_ident(_lia_char_code_at(t, 5)) == false)) { return "" ;}
  return cfs_body(t);

}

pub fn cfs_stmt(st: []const u8) []const u8 {
    var e: []const u8 = "";
    var n: i64 = 0;
    var out: []const u8 = "";
    var p: i64 = 0;
    var cl: i64 = 0;
    var w_cond: []const u8 = "";
    var w_body: []const u8 = "";
    var w_len: i64 = 0;
    var hdr: []const u8 = "";
    var s1: i64 = 0;
    var s2: i64 = 0;
    var f_init: []const u8 = "";
    var f_cond: []const u8 = "";
    var hdr_len: i64 = 0;
    var f_step: []const u8 = "";
    var f_body: []const u8 = "";
    var f_len: i64 = 0;
    var id: []const u8 = "";

  e = jss_trim(st);
  n = _lia_len(e);
  while (n >= 2  and  _lia_char_code_at(e, 0) == 123  and  _lia_char_code_at(e, n - 1) == 125) {
    e = jss_trim(slice2(e, 1, n - 1));
    n = _lia_len(e);
  }
  out = "";
  if (n == 0) { return out ;}
  p = 0;
  cl = 0;
  if (starts_lit(e, 0, "return") == 1  and  (n == 6  or  is_ident(_lia_char_code_at(e, 6)) == false)) {
    out = _lia_cat(out ,  "^");
    out = _lia_cat(out ,  cfs_shifts(jss_trim(slice2(e, 6, n))));
    return out;
  }
  if (starts_lit(e, 0, "if") == 1  and  n > 2  and  is_ident(_lia_char_code_at(e, 2)) == false) {
    p = skip_ws(e, 2);
    if (p < n  and  _lia_char_code_at(e, p) == 40) {
      cl = match_paren(e, p);
      if (cl > p) {
        out = _lia_cat(out ,  "?(");
        out = _lia_cat(out ,  cfs_shifts(slice2(e, p + 1, cl)));
        out = _lia_cat(out ,  "){ ");
        out = _lia_cat(out ,  cfs_brace_body(slice2(e, cl + 1, n)));
        out = _lia_cat(out ,  " }");
        return out;
      }
    }
  }
  if (starts_lit(e, 0, "while") == 1  and  n > 5  and  is_ident(_lia_char_code_at(e, 5)) == false) {
    p = skip_ws(e, 5);
    if (p < n  and  _lia_char_code_at(e, p) == 40) {
      cl = match_paren(e, p);
      if (cl > p) {
        w_cond = jss_trim(cfs_shifts(slice2(e, p + 1, cl)));
        w_body = jss_trim(slice2(e, cl + 1, n));
        w_len = _lia_len(w_body);
        while (w_len >= 2  and  _lia_char_code_at(w_body, 0) == 123  and  _lia_char_code_at(w_body, w_len - 1) == 125) {
          w_body = jss_trim(slice2(w_body, 1, w_len - 1));
          w_len = _lia_len(w_body);
        }
        out = "";
        out = _lia_cat(out ,  "while (");
        out = _lia_cat(out ,  w_cond);
        out = _lia_cat(out ,  ") {");
        out = _lia_cat(out ,  rgs_ch(10));
        if (_lia_len(w_body) > 0) {
          out = _lia_cat(out ,  cfs_body(w_body));
        }
        out = _lia_cat(out ,  "  }");
        return out;
      }
    }
  }
  if (starts_lit(e, 0, "for") == 1  and  n > 3  and  is_ident(_lia_char_code_at(e, 3)) == false) {
    p = skip_ws(e, 3);
    if (p < n  and  _lia_char_code_at(e, p) == 40) {
      cl = match_paren(e, p);
      if (cl > p) {
        hdr = slice2(e, p + 1, cl);
        s1 = cfs_find_semi(hdr, 0);
        if (s1 >= 0) {
          s2 = cfs_find_semi(hdr, s1 + 1);
          if (s2 >= 0) {
            f_init = jss_trim(slice2(hdr, 0, s1));
            f_cond = jss_trim(slice2(hdr, s1 + 1, s2));
            hdr_len = _lia_len(hdr);
            f_step = jss_trim(slice2(hdr, s2 + 1, hdr_len));
            f_body = jss_trim(slice2(e, cl + 1, n));
            f_len = _lia_len(f_body);
            while (f_len >= 2  and  _lia_char_code_at(f_body, 0) == 123  and  _lia_char_code_at(f_body, f_len - 1) == 125) {
              f_body = jss_trim(slice2(f_body, 1, f_len - 1));
              f_len = _lia_len(f_body);
            }
            out = "";
            if (_lia_len(f_init) > 0) {
              out = _lia_cat(out ,  cfs_stmt(f_init));
              out = _lia_cat(out ,  ";");
              out = _lia_cat(out ,  rgs_ch(10));
              out = _lia_cat(out ,  "  ");
            }
            out = _lia_cat(out ,  "while (");
            out = _lia_cat(out ,  cfs_shifts(f_cond));
            out = _lia_cat(out ,  ") {");
            out = _lia_cat(out ,  rgs_ch(10));
            if (_lia_len(f_body) > 0) {
              out = _lia_cat(out ,  cfs_body(f_body));
            }
            if (_lia_len(f_step) > 0) {
              out = _lia_cat(out ,  "  ");
              out = _lia_cat(out ,  cfs_step_to_assign(f_step));
              out = _lia_cat(out ,  ";");
              out = _lia_cat(out ,  rgs_ch(10));
            }
            out = _lia_cat(out ,  "  }");
            return out;
          }
        }
      }
    }
  }
  id = read_ident(e, 0);
  if (_lia_len(id) > 0) {
    p = skip_ws(e, _lia_len(id));
    if (starts_lit(e, p, "^=") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " ^ (");
      out = _lia_cat(out ,  cfs_shifts(jss_trim(slice2(e, p + 2, n))));
      out = _lia_cat(out ,  ")");
      return out;
    }
    if (starts_lit(e, p, "*=") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " * (");
      out = _lia_cat(out ,  cfs_shifts(jss_trim(slice2(e, p + 2, n))));
      out = _lia_cat(out ,  ")");
      return out;
    }
    if (starts_lit(e, p, "+=") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " + (");
      out = _lia_cat(out ,  cfs_shifts(jss_trim(slice2(e, p + 2, n))));
      out = _lia_cat(out ,  ")");
      return out;
    }
    if (starts_lit(e, p, "-=") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " - (");
      out = _lia_cat(out ,  cfs_shifts(jss_trim(slice2(e, p + 2, n))));
      out = _lia_cat(out ,  ")");
      return out;
    }
    if (starts_lit(e, p, "&=") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = ");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " & (");
      out = _lia_cat(out ,  cfs_shifts(jss_trim(slice2(e, p + 2, n))));
      out = _lia_cat(out ,  ")");
      return out;
    }
    if (starts_lit(e, p, ">>=") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = _lia_ushr(");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  ", ");
      out = _lia_cat(out ,  cfs_shifts(jss_trim(slice2(e, p + 3, n))));
      out = _lia_cat(out ,  ")");
      return out;
    }
    if (starts_lit(e, p, "<<=") == 1) {
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  " = _lia_shl(");
      out = _lia_cat(out ,  id);
      out = _lia_cat(out ,  ", ");
      out = _lia_cat(out ,  cfs_shifts(jss_trim(slice2(e, p + 3, n))));
      out = _lia_cat(out ,  ")");
      return out;
    }
    if (_lia_len(id) == n) {
      return "";
    }
  }
  out = _lia_cat(out ,  cfs_shifts(e));
  return out;

}

pub fn cfs_body(b: []const u8) []const u8 {
    var t: []const u8 = "";
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var st: i64 = 0;
    var d: i64 = 0;
    var c: i64 = 0;
    var seg: []const u8 = "";
    var conv: []const u8 = "";

  t = jss_trim(cfs_braces_to_arr(cfs_strip_types(cfs_strip_casts(b))));
  out = "";
  n = _lia_len(t);
  i = 0;
  st = 0;
  d = 0;
  c = 0;
  seg = "";
  conv = "";
  while (i <= n) {
    if (i == n  or  (d == 0  and  _lia_char_code_at(t, i) == 59)) {
      seg = jss_trim(slice2(t, st, i));
      if (_lia_len(seg) > 0) {
        conv = cfs_stmt(seg);
        if (_lia_len(conv) > 0) {
          out = _lia_cat(out ,  "  ");
          out = _lia_cat(out ,  conv);
          out = _lia_cat(out ,  ";");
          out = _lia_cat(out ,  rgs_ch(10));
        }
      }
      st = i + 1;
      i = i + 1;
      continue;
    }
    c = _lia_char_code_at(t, i);
    if (c == 40  or  c == 123  or  c == 91) { d = d + 1 ;}
    if (c == 41  or  c == 125  or  c == 93) {
      d = d - 1;
      if (d == 0  and  c == 125) {
        seg = jss_trim(slice2(t, st, i + 1));
        if (_lia_len(seg) > 0) {
          conv = cfs_stmt(seg);
          if (_lia_len(conv) > 0) {
            out = _lia_cat(out ,  "  ");
            out = _lia_cat(out ,  conv);
            out = _lia_cat(out ,  ";");
            out = _lia_cat(out ,  rgs_ch(10));
          }
        }
        st = i + 1;
      }
    }
    i = i + 1;
  }
  return out;

}

pub fn cfs_pdecl(params: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var seen: i64 = 0;
    var id: []const u8 = "";
    var last: []const u8 = "";

  out = "";
  n = _lia_len(params);
  i = 0;
  seen = 0;
  id = "";
  last = "";
  while (i < n) {
    id = read_ident(params, i);
    if (_lia_len(id) > 0) {
      if (cfs_is_type(id) == 0  and  cfs_kw(id) == 0) { last = id ;}
      i = i + _lia_len(id);
      continue;
    }
    if (_lia_char_code_at(params, i) == 44  or  i + 1 >= n) {
      if (_lia_len(last) > 0) {
        if (seen == 1) { out = _lia_cat(out ,  ", ") ;}
        out = _lia_cat(out ,  last);
        out = _lia_cat(out ,  ": int");
        seen = 1;
        last = "";
      }
    }
    i = i + 1;
  }
  if (_lia_len(last) > 0) {
    if (seen == 1) { out = _lia_cat(out ,  ", ") ;}
    out = _lia_cat(out ,  last);
    out = _lia_cat(out ,  ": int");
  }
  return out;

}

pub fn cfs_ret_u32(s: []const u8) i64 {
    var n: i64 = 0;
    var i: i64 = 0;
    var tl: []const u8 = "";
    var a: []const u8 = "";
    var k: i64 = 0;
    var en: i64 = 0;
    var id: []const u8 = "";

  n = _lia_len(s);
  i = n - 1;
  tl = "";
  a = "";
  k = 0;
  while (i >= 0  and  k < 2) {
    while (i >= 0  and  (_lia_char_code_at(s, i) == 32  or  _lia_char_code_at(s, i) == 9  or  _lia_char_code_at(s, i) == 10)) { i = i - 1 ;}
    if (i < 0) { break ;}
    if (is_ident(_lia_char_code_at(s, i)) == false) { break ;}
    en = i + 1;
    while (i > 0  and  is_ident(_lia_char_code_at(s, i - 1)) == true) { i = i - 1 ;}
    id = slice2(s, i, en);
    if (k == 0) { tl = id ;}  else { a = id ;}
    k = k + 1;
  }
  if (starts_lit(tl, 0, "uint32_t") == 1  and  _lia_len(tl) == 8) { return 1 ;}
  if (starts_lit(tl, 0, "uint") == 1  and  _lia_len(tl) == 4) { return 1 ;}
  if (starts_lit(tl, 0, "unsigned") == 1  and  _lia_len(tl) == 8) { return 1 ;}
  if (starts_lit(tl, 0, "int") == 1  and  _lia_len(tl) == 3) {
    if (starts_lit(a, 0, "unsigned") == 1  and  _lia_len(a) == 8) { return 1 ;}
  }
  return 0;

}

pub fn cfs_fn_apply_u32(out: []const u8) []const u8 {
    var n: i64 = 0;
    var k: i64 = 0;
    var lp: i64 = 0;
    var e: i64 = 0;
    var s2: i64 = 0;
    var res: []const u8 = "";

  n = _lia_len(out);
  k = n - 1;
  lp = -1;
  while (k >= 0  and  lp < 0) {
    if (_lia_char_code_at(out, k) == 94) { lp = k ;}  else { k = k - 1 ;}
  }
  if (lp < 0) { return out ;}
  e = skip_ws(out, lp + 1);
  s2 = cfs_find_semi(out, e);
  if (s2 > e) {
    res = "";
    res = _lia_cat(res ,  slice2(out, 0, lp));
    res = _lia_cat(res ,  "^(");
    res = _lia_cat(res ,  slice2(out, lp + 1, s2));
    res = _lia_cat(res ,  " & 4294967295)");
    res = _lia_cat(res ,  slice2(out, s2, n));
    return res;
  }
  return out;

}

pub fn cfs_fn(nm: []const u8, params: []const u8, body: []const u8, u32r: i64) []const u8 {
    var out: []const u8 = "";

  out = "";
  out = _lia_cat(out ,  "!");
  out = _lia_cat(out ,  nm);
  out = _lia_cat(out ,  "(");
  out = _lia_cat(out ,  cfs_pdecl(params));
  out = _lia_cat(out ,  "): int {");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  cfs_body(body));
  out = _lia_cat(out ,  "}");
  out = _lia_cat(out ,  rgs_ch(10));
  if (u32r == 1) { return cfs_fn_apply_u32(out) ;}
  return out;

}

pub fn cfs_name_before(s: []const u8, op: i64) []const u8 {
    var k: i64 = 0;
    var st: i64 = 0;

  k = op - 1;
  while (k >= 0  and  (_lia_char_code_at(s, k) == 32  or  _lia_char_code_at(s, k) == 9  or  _lia_char_code_at(s, k) == 10)) { k = k - 1 ;}
  if (k < 0  or  is_ident(_lia_char_code_at(s, k)) == false) { return "" ;}
  st = k;
  while (st > 0  and  is_ident(_lia_char_code_at(s, st - 1)) == true) { st = st - 1 ;}
  return read_ident(s, st);

}

pub fn cfs_prep(src: []const u8) []const u8 {

  return jss_rewrite_hex(jss_strip_comments(src));

}

pub fn cfs_from_c(src: []const u8) []const u8 {
    var pass: []const u8 = "";
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var op: i64 = 0;
    var cl: i64 = 0;
    var b: i64 = 0;
    var cb: i64 = 0;
    var nm: []const u8 = "";
    var pr: []const u8 = "";
    var bd: []const u8 = "";
    var reason: []const u8 = "";
    var names: []const u8 = "";

  pass = jss_trim(cfs_prep(src));
  out = "";
  out = jss_ln(out, "@LIN:L1c:0.2");
  out = jss_ln(out, "@FROM_C{source=transpiled scope=scalar_and_fixed_int_array}");
  out = jss_ln(out, "");
  n = _lia_len(pass);
  i = 0;
  op = 0;
  cl = 0;
  b = 0;
  cb = 0;
  nm = "";
  pr = "";
  bd = "";
  reason = "";
  names = "";
  while (i < n) {
    if (_lia_char_code_at(pass, i) == 40) {
      nm = cfs_name_before(pass, i);
      if (_lia_len(nm) > 0  and  cfs_kw(nm) == 0) {
        cl = match_paren(pass, i);
        if (cl > i) {
          b = skip_ws(pass, cl + 1);
          if (b < n  and  _lia_char_code_at(pass, b) == 123) {
            cb = match_brace(pass, b);
            if (cb > b) {
              pr = slice2(pass, i + 1, cl);
              bd = slice2(pass, b + 1, cb);
              reason = cfs_reason(slice2(pass, i, cl + 1), bd);
              if (starts_lit(reason, 0, "OK") == 1  and  _lia_len(reason) == 2) {
                out = _lia_cat(out ,  cfs_fn(nm, pr, bd, cfs_ret_u32(slice2(pass, 0, i - _lia_len(nm)))));
                names = rgs_csv_add(names, nm);
              }
              i = cb + 1;
              continue;
            }
          }
        }
      }
    }
    i = i + 1;
  }
  out = _lia_cat(out ,  "=ex{");
  out = _lia_cat(out ,  names);
  out = _lia_cat(out ,  "}");
  out = _lia_cat(out ,  rgs_ch(10));
  return out;

}

pub fn cfs_report(src: []const u8) []const u8 {
    var pass: []const u8 = "";
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var cl: i64 = 0;
    var b: i64 = 0;
    var cb: i64 = 0;
    var nm: []const u8 = "";
    var pr: []const u8 = "";
    var bd: []const u8 = "";
    var reason: []const u8 = "";
    var found: i64 = 0;
    var ok: i64 = 0;

  pass = jss_trim(cfs_prep(src));
  out = "";
  out = jss_ln(out, "@RULEL:LIN_FROM_C:1.0.0");
  out = jss_ln(out, ".fns{");
  n = _lia_len(pass);
  i = 0;
  cl = 0;
  b = 0;
  cb = 0;
  nm = "";
  pr = "";
  bd = "";
  reason = "";
  found = 0;
  ok = 0;
  while (i < n) {
    if (_lia_char_code_at(pass, i) == 40) {
      nm = cfs_name_before(pass, i);
      if (_lia_len(nm) > 0  and  cfs_kw(nm) == 0) {
        cl = match_paren(pass, i);
        if (cl > i) {
          b = skip_ws(pass, cl + 1);
          if (b < n  and  _lia_char_code_at(pass, b) == 123) {
            cb = match_brace(pass, b);
            if (cb > b) {
              pr = slice2(pass, i + 1, cl);
              bd = slice2(pass, b + 1, cb);
              reason = cfs_reason(slice2(pass, i, cl + 1), bd);
              found = found + 1;
              if (starts_lit(reason, 0, "OK") == 1  and  _lia_len(reason) == 2) { ok = ok + 1 ;}
              out = _lia_cat(out ,  "  .fn{ name=");
              out = _lia_cat(out ,  q());
              out = _lia_cat(out ,  nm);
              out = _lia_cat(out ,  q());
              out = _lia_cat(out ,  " reason=");
              out = _lia_cat(out ,  reason);
              out = _lia_cat(out ,  " }");
              out = _lia_cat(out ,  rgs_ch(10));
              i = cb + 1;
              continue;
            }
          }
        }
      }
    }
    i = i + 1;
  }
  out = jss_ln(out, "}");
  out = _lia_cat(out ,  ".found=");
  out = _lia_cat(out ,  rgs_num(found));
  out = _lia_cat(out ,  " .eligible=");
  out = _lia_cat(out ,  rgs_num(ok));
  out = _lia_cat(out ,  rgs_ch(10));
  return out;

}

pub fn ck_line(src: []const u8, at: i64) i64 {
    var ln: i64 = 0;
    var k: i64 = 0;
    var n: i64 = 0;

  ln = 1;
  k = 0;
  n = _lia_len(src);
  while (k < at  and  k < n) {
    if (_lia_char_code_at(src, k) == 10) { ln = ln + 1 ;}
    k = k + 1;
  }
  return ln;

}

pub fn ck_col(src: []const u8, at: i64) i64 {
    var k: i64 = 0;
    var col: i64 = 0;

  k = at;
  col = 1;
  while (k > 0  and  _lia_char_code_at(src, k - 1) != 10) { col = col + 1; k = k - 1 ;}
  return col;

}

pub fn ck_heur_str(id: []const u8) i64 {

  if (_lia_len(id) == 0) { return 0 ;}
  if (starts_lit(id, 0, "q") == 1) { return 1 ;}
  if (starts_lit(id, 0, "body") == 1) { return 1 ;}
  if (starts_lit(id, 0, "params") == 1) { return 1 ;}
  if (starts_lit(id, 0, "names") == 1) { return 1 ;}
  if (starts_lit(id, 0, "chs") == 1) { return 1 ;}
  if (starts_lit(id, 0, "out") == 1) { return 1 ;}
  if (starts_lit(id, 0, "js_p") == 1) { return 1 ;}
  if (starts_lit(id, 0, "rewrite_") == 1) { return 1 ;}
  if (starts_lit(id, 0, "lin_") == 1) { return 1 ;}
  if (starts_lit(id, 0, "zig_") == 1) { return 1 ;}
  if (starts_lit(id, 0, "emit_") == 1) { return 1 ;}
  if (starts_lit(id, 0, "param_") == 1) { return 1 ;}
  if (starts_lit(id, 0, "fn_ret") == 1) { return 1 ;}
  if (starts_lit(id, 0, "andor") == 1) { return 1 ;}
  if (starts_lit(id, 0, "kw_space") == 1) { return 1 ;}
  if (starts_lit(id, 0, "rgs_") == 1) { return 1 ;}
  if (starts_lit(id, 0, "jss_") == 1) { return 1 ;}
  if (starts_lit(id, 0, "cks_") == 1) { return 1 ;}
  if (starts_lit(id, 0, "slice2") == 1) { return 1 ;}
  if (starts_lit(id, 0, "read_ident") == 1) { return 1 ;}
  if (starts_lit(id, 0, "fromCharCode") == 1) { return 1 ;}
  if (starts_lit(id, 0, "charAt") == 1) { return 1 ;}
  if (_lia_len(id) == 2  and  starts_lit(id, 0, "id") == 1) { return 1 ;}
  if (_lia_len(id) == 3  and  starts_lit(id, 0, "src") == 1) { return 1 ;}
  return 0;

}

pub fn cks_diag(src: []const u8, at: i64, code: []const u8, fix: []const u8) []const u8 {
    var out: []const u8 = "";

  out = "  .d{ code=";
  out = _lia_cat(out ,  code);
  out = _lia_cat(out ,  " line=");
  out = _lia_cat(out ,  rgs_num(ck_line(src, at)));
  out = _lia_cat(out ,  " col=");
  out = _lia_cat(out ,  rgs_num(ck_col(src, at)));
  out = _lia_cat(out ,  " fix=");
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  fix);
  out = _lia_cat(out ,  q());
  out = _lia_cat(out ,  " }");
  out = _lia_cat(out ,  rgs_ch(10));
  return out;

}

pub fn ck_side_literal(src: []const u8, at: i64, oplen: i64) i64 {
    var n: i64 = 0;
    var k: i64 = 0;

  n = _lia_len(src);
  k = at - 1;
  while (k >= 0  and  (_lia_char_code_at(src, k) == 32  or  _lia_char_code_at(src, k) == 9)) { k = k - 1 ;}
  if (k >= 0  and  _lia_char_code_at(src, k) == 34) { return 1 ;}
  k = skip_ws(src, at + oplen);
  if (k < n  and  _lia_char_code_at(src, k) == 34) { return 1 ;}
  return 0;

}

pub fn ck_call_left_str(src: []const u8, at: i64) i64 {
    var k: i64 = 0;
    var d: i64 = 0;
    var nm: []const u8 = "";
    var st: i64 = 0;

  k = at - 1;
  d = 0;
  nm = "";
  st = 0;
  while (k >= 0  and  (_lia_char_code_at(src, k) == 32  or  _lia_char_code_at(src, k) == 9)) { k = k - 1 ;}
  if (k < 0) { return 0 ;}
  if (_lia_char_code_at(src, k) != 41) { return 0 ;}
  while (k >= 0) {
    if (_lia_char_code_at(src, k) == 41) { d = d + 1 ;}
    if (_lia_char_code_at(src, k) == 40) {
      d = d - 1;
      if (d == 0) {
        if (k == 0) { return 0 ;}
        if (is_ident(_lia_char_code_at(src, k - 1)) == false) { return 0 ;}
        st = k - 1;
        while (st > 0  and  is_ident(_lia_char_code_at(src, st - 1)) == true) { st = st - 1 ;}
        nm = read_ident(src, st);
        return ck_heur_str(nm);
      }
    }
    k = k - 1;
  }
  return 0;

}

pub fn cks_ops(src: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var c: i64 = 0;

  out = "";
  n = _lia_len(src);
  i = 0;
  c = 0;
  while (i < n) {
    c = _lia_char_code_at(src, i);
    if (c == 34) {
      i = i + 1;
      while (i < n  and  _lia_char_code_at(src, i) != 34) {
        if (_lia_char_code_at(src, i) == 92) {
          out = _lia_cat(out ,  cks_diag(src, i, "ESCAPE_IN_LITERAL", "literals carry no escapes; call q() to emit a quote"));
        }
        i = i + 1;
      }
      i = i + 1;
      continue;
    }
    if (c == 47  and  i + 1 < n  and  _lia_char_code_at(src, i + 1) == 47) {
      while (i < n  and  _lia_char_code_at(src, i) != 10) { i = i + 1 ;}
      continue;
    }
    if (c == 47) {
      out = _lia_cat(out ,  cks_diag(src, i, "INT_DIVISION", "no integer division; subtract in a loop or pass a power of ten"));
      i = i + 1;
      continue;
    }
    if (c == 60  and  i + 1 < n  and  _lia_char_code_at(src, i + 1) == 60) {
      out = _lia_cat(out ,  cks_diag(src, i, "SHIFT_OPERATOR", "no shift operator; call _lia_shl(a, b)"));
      i = i + 2;
      continue;
    }
    if (c == 62  and  i + 1 < n  and  _lia_char_code_at(src, i + 1) == 62) {
      out = _lia_cat(out ,  cks_diag(src, i, "SHIFT_OPERATOR", "no shift operator; call _lia_shr(a, b)"));
      i = i + 2;
      continue;
    }
    if (c == 61  and  i + 1 < n  and  _lia_char_code_at(src, i + 1) == 61) {
      if (ck_side_literal(src, i, 2) == 1) {
        out = _lia_cat(out ,  cks_diag(src, i, "STRING_COMPARE", "no string equality; compare .length then starts_lit(s, 0, lit)"));
      }
      i = i + 2;
      continue;
    }
    if (c == 33  and  i + 1 < n  and  _lia_char_code_at(src, i + 1) == 61) {
      if (ck_side_literal(src, i, 2) == 1) {
        out = _lia_cat(out ,  cks_diag(src, i, "STRING_COMPARE", "no string inequality; compare .length then starts_lit(s, 0, lit)"));
      }
      i = i + 2;
      continue;
    }
    if (c == 43  and  i + 1 < n  and  _lia_char_code_at(src, i + 1) == 43) {
      i = i + 2;
      continue;
    }
    if (c == 43) {
      if (ck_call_left_str(src, i) == 1) {
        out = _lia_cat(out ,  cks_diag(src, i, "CALL_LEFT_OF_CONCAT", "bind the call result to a variable first, then concatenate"));
      }
      i = i + 1;
      continue;
    }
    i = i + 1;
  }
  return out;

}

pub fn cks_plist(src: []const u8, plist: []const u8, at: i64) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var st: i64 = 0;
    var nm: []const u8 = "";
    var ty: []const u8 = "";
    var p: i64 = 0;
    var seg: []const u8 = "";
    var p0: i64 = 0;

  out = "";
  n = _lia_len(plist);
  i = 0;
  st = 0;
  nm = "";
  ty = "";
  p = 0;
  seg = "";
  while (i <= n) {
    if (i == n  or  _lia_char_code_at(plist, i) == 44) {
      seg = slice2(plist, st, i);
      nm = read_ident(seg, skip_ws(seg, 0));
      if (_lia_len(nm) > 0) {
        p0 = skip_ws(seg, 0);
        p = skip_ws(seg, p0 + _lia_len(nm));
        ty = "";
        if (p < _lia_len(seg)  and  _lia_char_code_at(seg, p) == 58) {
          ty = read_ident(seg, skip_ws(seg, p + 1));
        }
        if (_lia_len(ty) > 0) {
          if (starts_lit(ty, 0, "string") == 0  and  starts_lit(ty, 0, "str") == 0  and  starts_lit(ty, 0, "bool") == 0) {
            if (ck_heur_str(nm) == 1) {
              out = _lia_cat(out ,  cks_diag(src, at, "NAME_TYPE_COLLISION", "parameter name is read as a string by the type heuristic; rename it"));
            }
          }
        }
      }
      st = i + 1;
      i = i + 1;
      continue;
    }
    i = i + 1;
  }
  return out;

}

pub fn cks_params(src: []const u8) []const u8 {
    var out: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var nm: []const u8 = "";
    var op: i64 = 0;
    var cl: i64 = 0;

  out = "";
  n = _lia_len(src);
  i = 0;
  nm = "";
  op = 0;
  cl = 0;
  while (i < n) {
    if (_lia_char_code_at(src, i) == 33) {
      nm = read_ident(src, i + 1);
      if (_lia_len(nm) > 0) {
        op = skip_ws(src, i + 1 + _lia_len(nm));
        if (op < n  and  _lia_char_code_at(src, op) == 40) {
          cl = match_paren(src, op);
          if (cl > op) {
            out = _lia_cat(out ,  cks_plist(src, slice2(src, op + 1, cl), op));
            i = cl;
          }
        }
      }
    }
    i = i + 1;
  }
  return out;

}

pub fn cks_lint(src: []const u8) []const u8 {
    var out: []const u8 = "";
    var body: []const u8 = "";

  out = "";
  body = "";
  body = _lia_cat(body ,  cks_ops(src));
  body = _lia_cat(body ,  cks_params(src));
  out = _lia_cat(out ,  "@RULEL:LIN_LINT:1.0.0");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  ".policy{ level=error fail_closed=true rationale=every_rejected_construct_names_its_supported_alternative }");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  ".diagnostics{");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  body);
  out = _lia_cat(out ,  "}");
  out = _lia_cat(out ,  rgs_ch(10));
  out = _lia_cat(out ,  ".summary{ errors=");
  out = _lia_cat(out ,  rgs_num(rg_count_lit(body, "  .d{")));
  out = _lia_cat(out ,  " }");
  out = _lia_cat(out ,  rgs_ch(10));
  return out;

}

pub fn ck_errors(src: []const u8) i64 {
    var body: []const u8 = "";

  body = "";
  body = _lia_cat(body ,  cks_ops(src));
  body = _lia_cat(body ,  cks_params(src));
  return rg_count_lit(body, "  .d{");

}


// LIN-HOST-BEGIN
pub const ParamTypeInfo = struct {
    name: []const u8,
    type_name: []const u8,
};

pub const FnTypeInfo = struct {
    name: []const u8,
    params: []ParamTypeInfo,
    return_type: []const u8,
    body: []const u8,
    line: usize,
};

fn is_valid_ident(s: []const u8) bool {
    if (s.len == 0) return false;
    for (s, 0..) |c, idx| {
        if (idx == 0) {
            if (!((c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or c == '_' or c == '$')) return false;
        } else {
            if (!((c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or (c >= '0' and c <= '9') or c == '_' or c == '$')) return false;
        }
    }
    return true;
}

fn is_integer_literal(s: []const u8) bool {
    if (s.len == 0) return false;
    var start: usize = 0;
    if (s[0] == '-' and s.len > 1) start = 1;
    for (s[start..]) |c| {
        if (c < '0' or c > '9') return false;
    }
    return true;
}

const OpParts = struct {
    left: []const u8,
    right: []const u8,
};

fn has_top_level_op(s: []const u8, op: []const u8) bool {
    var in_quote = false;
    var paren_depth: i64 = 0;
    var brace_depth: i64 = 0;
    var i: usize = 0;
    while (i < s.len) {
        const c = s[i];
        if (c == '"') {
            in_quote = !in_quote;
            i += 1;
            continue;
        }
        if (!in_quote) {
            if (c == '(') paren_depth += 1
            else if (c == ')') paren_depth -= 1
            else if (c == '{') brace_depth += 1
            else if (c == '}') brace_depth -= 1
            else if (paren_depth == 0 and brace_depth == 0) {
                if (i + op.len <= s.len and std.mem.eql(u8, s[i .. i + op.len], op)) {
                    return true;
                }
            }
        }
        i += 1;
    }
    return false;
}

fn split_top_level_op(s: []const u8, op_ch: u8) ?OpParts {
    var in_quote = false;
    var paren_depth: i64 = 0;
    var brace_depth: i64 = 0;
    var i: usize = 0;
    while (i < s.len) {
        const c = s[i];
        if (c == '"') {
            in_quote = !in_quote;
            i += 1;
            continue;
        }
        if (!in_quote) {
            if (c == '(') paren_depth += 1
            else if (c == ')') paren_depth -= 1
            else if (c == '{') brace_depth += 1
            else if (c == '}') brace_depth -= 1
            else if (paren_depth == 0 and brace_depth == 0 and c == op_ch) {
                return OpParts{
                    .left = s[0..i],
                    .right = s[i + 1 ..],
                };
            }
        }
        i += 1;
    }
    return null;
}

fn find_matching_paren(s: []const u8, open_idx: usize) ?usize {
    var in_quote = false;
    var depth: i64 = 0;
    var i: usize = open_idx;
    while (i < s.len) {
        const c = s[i];
        if (c == '"') {
            in_quote = !in_quote;
            i += 1;
            continue;
        }
        if (!in_quote) {
            if (c == '(') depth += 1
            else if (c == ')') {
                depth -= 1;
                if (depth == 0) return i;
            }
        }
        i += 1;
    }
    return null;
}

fn split_call_args(allocator: std.mem.Allocator, raw: []const u8) ![][]const u8 {
    var args = std.ArrayList([]const u8).init(allocator);
    var start: usize = 0;
    var in_quote = false;
    var paren_depth: i64 = 0;
    var brace_depth: i64 = 0;
    var i: usize = 0;
    while (i <= raw.len) {
        if (i == raw.len) {
            const item = std.mem.trim(u8, raw[start..i], " \t\r\n");
            if (item.len > 0) try args.append(item);
            break;
        }
        const c = raw[i];
        if (c == '"') in_quote = !in_quote;
        if (!in_quote) {
            if (c == '(') paren_depth += 1
            else if (c == ')') paren_depth -= 1
            else if (c == '{') brace_depth += 1
            else if (c == '}') brace_depth -= 1
            else if (paren_depth == 0 and brace_depth == 0 and c == ',') {
                const item = std.mem.trim(u8, raw[start..i], " \t\r\n");
                if (item.len > 0) try args.append(item);
                start = i + 1;
            }
        }
        i += 1;
    }
    return args.toOwnedSlice();
}

pub fn infer_expr_type(expr: []const u8, locals: *const std.StringHashMap([]const u8), fns: []const FnTypeInfo) []const u8 {
    const trimmed = std.mem.trim(u8, expr, " \t\r\n;");
    if (trimmed.len == 0) return "any";

    // String literal: "..."
    if (trimmed.len >= 2 and trimmed[0] == '"' and trimmed[trimmed.len - 1] == '"') {
        return "string";
    }

    // Boolean literal: true / false
    if (std.mem.eql(u8, trimmed, "true") or std.mem.eql(u8, trimmed, "false")) {
        return "bool";
    }

    // Single identifier
    if (is_valid_ident(trimmed)) {
        if (locals.get(trimmed)) |t| {
            return t;
        }
        return "any";
    }

    // Integer literal
    if (is_integer_literal(trimmed)) {
        return "int";
    }

    // Function call: name(...)
    if (std.mem.indexOfScalar(u8, trimmed, '(')) |oparen| {
        if (trimmed[trimmed.len - 1] == ')') {
            const callee_name = std.mem.trim(u8, trimmed[0..oparen], " \t");
            for (fns) |f| {
                if (std.mem.eql(u8, f.name, callee_name)) {
                    return f.return_type;
                }
            }
        }
    }

    // Comparison operators (==, !=, <=, >=, <, >) outside quotes/parens
    if (has_top_level_op(trimmed, "==") or has_top_level_op(trimmed, "!=") or
        has_top_level_op(trimmed, "<=") or has_top_level_op(trimmed, ">=") or
        has_top_level_op(trimmed, "<") or has_top_level_op(trimmed, ">"))
    {
        return "bool";
    }

    // Logical operators (&&, ||, and, or)
    if (has_top_level_op(trimmed, "&&") or has_top_level_op(trimmed, "||") or
        has_top_level_op(trimmed, " and ") or has_top_level_op(trimmed, " or "))
    {
        return "bool";
    }

    // Arithmetic operators (+, -, *, /, %)
    if (has_top_level_op(trimmed, "+")) {
        if (split_top_level_op(trimmed, '+')) |parts| {
            const t_left = infer_expr_type(parts.left, locals, fns);
            const t_right = infer_expr_type(parts.right, locals, fns);
            if (std.mem.eql(u8, t_left, "string") or std.mem.eql(u8, t_right, "string")) {
                return "string";
            }
            if (std.mem.eql(u8, t_left, "int") and std.mem.eql(u8, t_right, "int")) {
                return "int";
            }
        }
        return "int";
    }

    if (has_top_level_op(trimmed, "-") or has_top_level_op(trimmed, "*") or
        has_top_level_op(trimmed, "/") or has_top_level_op(trimmed, "%"))
    {
        return "int";
    }

    // Parenthesized expression: (expr)
    if (trimmed.len >= 2 and trimmed[0] == '(' and trimmed[trimmed.len - 1] == ')') {
        return infer_expr_type(trimmed[1 .. trimmed.len - 1], locals, fns);
    }

    return "any";
}

pub fn parse_fn_type_infos(allocator: std.mem.Allocator, src: []const u8) ![]FnTypeInfo {
    var list = std.ArrayList(FnTypeInfo).init(allocator);
    var i: usize = 0;
    var current_line: usize = 1;

    while (i < src.len) {
        if (src[i] == '\n') current_line += 1;
        if (src[i] == '!' and (i + 1 >= src.len or src[i + 1] != '=')) {
            const fn_line = current_line;
            var pos = i + 1;
            while (pos < src.len and (src[pos] == ' ' or src[pos] == '\t' or src[pos] == '\r' or src[pos] == '\n')) {
                if (src[pos] == '\n') current_line += 1;
                pos += 1;
            }
            const name_start = pos;
            while (pos < src.len and ((src[pos] >= 'a' and src[pos] <= 'z') or (src[pos] >= 'A' and src[pos] <= 'Z') or (src[pos] >= '0' and src[pos] <= '9') or src[pos] == '_' or src[pos] == '$')) {
                pos += 1;
            }
            const fn_name = src[name_start..pos];
            if (fn_name.len > 0 and pos < src.len and src[pos] == '(') {
                const open_p = pos;
                var paren_depth: i64 = 1;
                pos += 1;
                while (pos < src.len and paren_depth > 0) {
                    if (src[pos] == '\n') current_line += 1;
                    if (src[pos] == '"') {
                        pos += 1;
                        while (pos < src.len and src[pos] != '"') {
                            if (src[pos] == '\n') current_line += 1;
                            pos += 1;
                        }
                        if (pos < src.len) pos += 1;
                        continue;
                    }
                    if (src[pos] == '(') paren_depth += 1
                    else if (src[pos] == ')') paren_depth -= 1;
                    pos += 1;
                }
                const close_p = pos - 1;
                const raw_params = src[open_p + 1 .. close_p];

                // Parse parameters
                var param_list = std.ArrayList(ParamTypeInfo).init(allocator);
                var p_it = std.mem.splitScalar(u8, raw_params, ',');
                while (p_it.next()) |p_raw| {
                    const p_trimmed = std.mem.trim(u8, p_raw, " \t\r\n");
                    if (p_trimmed.len == 0) continue;
                    if (std.mem.indexOfScalar(u8, p_trimmed, ':')) |colon_idx| {
                        const p_name = std.mem.trim(u8, p_trimmed[0..colon_idx], " \t\r\n");
                        const p_type = std.mem.trim(u8, p_trimmed[colon_idx + 1 ..], " \t\r\n");
                        try param_list.append(.{ .name = p_name, .type_name = p_type });
                    } else {
                        try param_list.append(.{ .name = p_trimmed, .type_name = "any" });
                    }
                }

                // Look for return type before '{'
                var hdr_end = pos;
                while (hdr_end < src.len and src[hdr_end] != '{') {
                    if (src[hdr_end] == '\n') current_line += 1;
                    hdr_end += 1;
                }
                const hdr_extra = src[pos..hdr_end];
                var ret_type: []const u8 = "any";
                if (std.mem.indexOf(u8, hdr_extra, "->")) |arrow_idx| {
                    ret_type = std.mem.trim(u8, hdr_extra[arrow_idx + 2 ..], " \t\r\n");
                } else if (std.mem.indexOfScalar(u8, hdr_extra, ':')) |colon_idx| {
                    ret_type = std.mem.trim(u8, hdr_extra[colon_idx + 1 ..], " \t\r\n");
                }

                // Extract body
                if (hdr_end < src.len and src[hdr_end] == '{') {
                    const brace_open = hdr_end;
                    var brace_depth: i64 = 1;
                    var bpos = brace_open + 1;
                    while (bpos < src.len and brace_depth > 0) {
                        if (src[bpos] == '\n') current_line += 1;
                        if (src[bpos] == '"') {
                            bpos += 1;
                            while (bpos < src.len and src[bpos] != '"') {
                                if (src[bpos] == '\n') current_line += 1;
                                bpos += 1;
                            }
                            if (bpos < src.len) bpos += 1;
                            continue;
                        }
                        if (src[bpos] == '{') brace_depth += 1
                        else if (src[bpos] == '}') brace_depth -= 1;
                        bpos += 1;
                    }
                    const brace_close = bpos - 1;
                    const body_text = src[brace_open + 1 .. brace_close];
                    try list.append(.{
                        .name = fn_name,
                        .params = try param_list.toOwnedSlice(),
                        .return_type = ret_type,
                        .body = body_text,
                        .line = fn_line,
                    });
                    i = bpos;
                    continue;
                }
            }
        }
        i += 1;
    }
    return list.toOwnedSlice();
}

pub fn lin_type_check(src: []const u8) ?[]const u8 {
    const fns = parse_fn_type_infos(LIA_ALLOC, src) catch return null;
    defer LIA_ALLOC.free(fns);

    for (fns) |fn_info| {
        var locals = std.StringHashMap([]const u8).init(LIA_ALLOC);
        defer locals.deinit();

        for (fn_info.params) |p| {
            locals.put(p.name, p.type_name) catch {};
        }

        // Scan statements inside function body
        var stmt_start: usize = 0;
        var in_quote = false;
        var paren_depth: i64 = 0;
        var brace_depth: i64 = 0;
        var idx: usize = 0;

        while (idx <= fn_info.body.len) {
            var is_stmt_end = false;
            if (idx == fn_info.body.len) {
                is_stmt_end = true;
            } else {
                const ch = fn_info.body[idx];
                if (ch == '"') in_quote = !in_quote;
                if (!in_quote) {
                    if (ch == '(') paren_depth += 1
                    else if (ch == ')') paren_depth -= 1
                    else if (ch == '{') brace_depth += 1
                    else if (ch == '}') brace_depth -= 1
                    else if (paren_depth == 0 and brace_depth == 0 and ch == ';') {
                        is_stmt_end = true;
                    }
                }
            }

            if (is_stmt_end) {
                const stmt = std.mem.trim(u8, fn_info.body[stmt_start..idx], " \t\r\n;");
                stmt_start = idx + 1;
                idx += 1;
                if (stmt.len == 0) continue;

                // Check assignment: var = expr
                if (std.mem.indexOfScalar(u8, stmt, '=')) |eq_idx| {
                    if (eq_idx > 0 and stmt[eq_idx - 1] != '=' and stmt[eq_idx - 1] != '!' and stmt[eq_idx - 1] != '<' and stmt[eq_idx - 1] != '>' and
                        (eq_idx + 1 >= stmt.len or stmt[eq_idx + 1] != '='))
                    {
                        const lhs = std.mem.trim(u8, stmt[0..eq_idx], " \t");
                        const rhs = std.mem.trim(u8, stmt[eq_idx + 1 ..], " \t");
                        if (is_valid_ident(lhs)) {
                            const rhs_type = infer_expr_type(rhs, &locals, fns);
                            locals.put(lhs, rhs_type) catch {};
                        }
                    }
                }

                // Check return statements: ^expr or return expr
                var ret_expr: ?[]const u8 = null;
                if (stmt[0] == '^') {
                    ret_expr = std.mem.trim(u8, stmt[1..], " \t");
                } else if (std.mem.startsWith(u8, stmt, "return ")) {
                    ret_expr = std.mem.trim(u8, stmt[7..], " \t");
                }

                if (ret_expr) |rx| {
                    const actual_ret_type = infer_expr_type(rx, &locals, fns);
                    if (!std.mem.eql(u8, fn_info.return_type, "any") and !std.mem.eql(u8, actual_ret_type, "any")) {
                        if (std.mem.eql(u8, fn_info.return_type, "int") and (std.mem.eql(u8, actual_ret_type, "string") or std.mem.eql(u8, actual_ret_type, "bool"))) {
                            return std.fmt.allocPrint(LIA_ALLOC, "LIN_TYPE_ERROR: function '{s}' return type mismatch: expected int, got {s}", .{ fn_info.name, actual_ret_type }) catch "LIN_TYPE_ERROR: return type mismatch";
                        }
                        if (std.mem.eql(u8, fn_info.return_type, "string") and (std.mem.eql(u8, actual_ret_type, "int") or std.mem.eql(u8, actual_ret_type, "bool"))) {
                            return std.fmt.allocPrint(LIA_ALLOC, "LIN_TYPE_ERROR: function '{s}' return type mismatch: expected string, got {s}", .{ fn_info.name, actual_ret_type }) catch "LIN_TYPE_ERROR: return type mismatch";
                        }
                        if (std.mem.eql(u8, fn_info.return_type, "bool") and (std.mem.eql(u8, actual_ret_type, "string") or std.mem.eql(u8, actual_ret_type, "int"))) {
                            return std.fmt.allocPrint(LIA_ALLOC, "LIN_TYPE_ERROR: function '{s}' return type mismatch: expected bool, got {s}", .{ fn_info.name, actual_ret_type }) catch "LIN_TYPE_ERROR: return type mismatch";
                        }
                    }
                }

                // Check function call argument types in statement
                for (fns) |callee| {
                    var search_pos: usize = 0;
                    while (std.mem.indexOfPos(u8, stmt, search_pos, callee.name)) |call_idx| {
                        const after_name = call_idx + callee.name.len;
                        search_pos = after_name;
                        if (call_idx > 0 and ((stmt[call_idx - 1] >= 'a' and stmt[call_idx - 1] <= 'z') or (stmt[call_idx - 1] >= 'A' and stmt[call_idx - 1] <= 'Z') or (stmt[call_idx - 1] >= '0' and stmt[call_idx - 1] <= '9') or stmt[call_idx - 1] == '_' or stmt[call_idx - 1] == '$')) continue;
                        if (after_name < stmt.len and stmt[after_name] == '(') {
                            if (find_matching_paren(stmt, after_name)) |close_call_p| {
                                const args_raw = stmt[after_name + 1 .. close_call_p];
                                const call_args = split_call_args(LIA_ALLOC, args_raw) catch null;
                                if (call_args) |args| {
                                    defer LIA_ALLOC.free(args);
                                    for (args, 0..) |arg_trimmed, arg_idx| {
                                        if (arg_idx < callee.params.len) {
                                            const expected_type = callee.params[arg_idx].type_name;
                                            const actual_type = infer_expr_type(arg_trimmed, &locals, fns);
                                            if (!std.mem.eql(u8, expected_type, "any") and !std.mem.eql(u8, actual_type, "any")) {
                                                if (!std.mem.eql(u8, expected_type, actual_type)) {
                                                    return std.fmt.allocPrint(LIA_ALLOC, "LIN_TYPE_ERROR: function '{s}' argument '{s}' expected type {s}, got {s}", .{ callee.name, callee.params[arg_idx].name, expected_type, actual_type }) catch "LIN_TYPE_ERROR: argument type mismatch";
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                idx += 1;
            }
        }
    }
    return null;
}

pub fn lin_syntax_valid(src: []const u8) i64 {
    var names: []const u8 = "";
    var n: i64 = 0;
    var i: i64 = 0;
    var depth: i64 = 0;
    var c: i64 = 0;

    names = "";
    n = @as(i64, @intCast(src.len));
    i = 0;
    depth = 0;
    c = 0;
    while (i < n) {
        c = _lia_char_code_at(src, i);
        if (c == 34) {
            i = i + 1;
            while (i < n and _lia_char_code_at(src, i) != 34) { i = i + 1; }
            if (i < n) { i = i + 1; }
            continue;
        }
        if (c == 123) { depth = depth + 1; }
        if (c == 125) {
            depth = depth - 1;
            if (depth < 0) { return 0; }
        }
        i = i + 1;
    }
    if (depth != 0) { return 0; }
    names = lin_check(src);
    if (@as(i64, @intCast(names.len)) == 0) { return 0; }
    return 1;
}

pub fn lin_valid_strict(src: []const u8) i64 {
    if (lin_syntax_valid(src) == 0) return 0;
    if (lin_type_check(src) != null) return 0;
    return 1;
}

pub fn lin_check_rulel(src: []const u8) []const u8 {
    const names = lin_check(src);
    const ex = read_exports(src);
    const h = read_header(src);
    const fns = parse_fn_type_infos(LIA_ALLOC, src) catch null;

    var out = std.ArrayList(u8).init(LIA_ALLOC);
    defer out.deinit();
    const ow = out.writer();
    ow.writeAll("@RULEL:LIN_CHECK:1.0.0\n") catch {};
    ow.print(".header=\"{s}\"\n", .{h}) catch {};
    ow.print(".fns={s}\n", .{csv_json_arr(names)}) catch {};
    ow.print(".exports={s}\n", .{csv_json_arr(ex)}) catch {};
    ow.writeAll(".types{\n") catch {};
    if (fns) |fn_list| {
        for (fn_list) |f| {
            ow.print("  .{s}{{ params=[", .{f.name}) catch {};
            for (f.params, 0..) |p, pidx| {
                if (pidx > 0) ow.writeAll(",") catch {};
                ow.print("\"{s}:{s}\"", .{ p.name, p.type_name }) catch {};
            }
            ow.print("] return=\"{s}\" }}\n", .{f.return_type}) catch {};
        }
    }
    ow.writeAll("}\n") catch {};
    ow.writeAll(".typecheck=passed\n") catch {};
    return out.toOwnedSlice() catch "@RULEL:LIN_CHECK:1.0.0\n.typecheck=failed\n";
}
// LinVM: in-memory execution engine for the integer subset of the dialect.
// It carries its own tokenizer, compiler and interpreter and shares no code
// path with lin_to_zig, so bit-exact agreement between the two is evidence of
// equivalence rather than a tautology.
// Declared semantics, which may diverge from the emitted binary and must be
// reported as such: arithmetic wraps on i64, shifts follow _lia_shl/_lia_shr,
// and remainder by zero yields zero instead of trapping.

pub const VmOp = enum(u8) {
    push_const,
    load_local,
    store_local,
    add,
    sub,
    mul,
    mod,
    bit_and,
    bit_or,
    bit_xor,
    bit_not,
    neg,
    shl,
    shr,
    ushr,
    cmp_eq,
    cmp_ne,
    cmp_lt,
    cmp_gt,
    cmp_le,
    cmp_ge,
    log_not,
    jump,
    jump_if_false,
    jump_if_false_keep,
    jump_if_true_keep,
    pop,
    call,
    ret,
    load_index,
    store_index,
    arr_len,
};

pub const VmIns = struct {
    op: VmOp,
    a: i64 = 0,
};

pub const VmFn = struct {
    name: []const u8,
    nparams: usize,
    nlocals: usize = 0,
    code: []VmIns = &[_]VmIns{},
    sig_ok: bool = false,
    ok: bool = false,
    reject: []const u8 = "",
    arr_n: []u16 = &[_]u16{},
};

pub const VmModule = struct {
    fns: []VmFn,
};

const VM_MAX_LOCALS: usize = 64;
const VM_MAX_STACK: usize = 256;
const VM_MAX_DEPTH: usize = 192;
const VM_STEP_LIMIT: u64 = 200_000_000;
const VM_MAX_ARRS: usize = 8;
const VM_MAX_ARR_LEN: usize = 256;

pub const VmError = error{
    VmStepLimit,
    VmStackOverflow,
    VmStackUnderflow,
    VmBadFunction,
    VmDepth,
    VmArity,
};

const VmTokKind = enum { ident, number, punct, str, eof };

const VmTok = struct {
    kind: VmTokKind,
    text: []const u8,
};

fn vmIsIdentStart(c: u8) bool {
    return (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or c == '_' or c == '$';
}

fn vmIsIdentPart(c: u8) bool {
    return vmIsIdentStart(c) or (c >= '0' and c <= '9');
}

fn vmTokenize(allocator: std.mem.Allocator, src: []const u8) ![]VmTok {
    var out = std.ArrayList(VmTok).init(allocator);
    var i: usize = 0;
    while (i < src.len) {
        const c = src[i];
        if (c == ' ' or c == '\t' or c == '\r' or c == '\n') {
            i += 1;
            continue;
        }
        if (c == '/' and i + 1 < src.len and src[i + 1] == '/') {
            while (i < src.len and src[i] != '\n') i += 1;
            continue;
        }
        if (c == '"') {
            const start = i;
            i += 1;
            while (i < src.len and src[i] != '"') {
                if (src[i] == '\\' and i + 1 < src.len) i += 1;
                i += 1;
            }
            if (i < src.len) i += 1;
            try out.append(.{ .kind = .str, .text = src[start..i] });
            continue;
        }
        if (c >= '0' and c <= '9') {
            const start = i;
            while (i < src.len and src[i] >= '0' and src[i] <= '9') i += 1;
            try out.append(.{ .kind = .number, .text = src[start..i] });
            continue;
        }
        if (vmIsIdentStart(c)) {
            const start = i;
            while (i < src.len and vmIsIdentPart(src[i])) i += 1;
            try out.append(.{ .kind = .ident, .text = src[start..i] });
            continue;
        }
        if (i + 1 < src.len) {
            const two = src[i .. i + 2];
            const is_two = std.mem.eql(u8, two, "==") or std.mem.eql(u8, two, "!=") or
                std.mem.eql(u8, two, "<=") or std.mem.eql(u8, two, ">=") or
                std.mem.eql(u8, two, "&&") or std.mem.eql(u8, two, "||") or
                std.mem.eql(u8, two, "->");
            if (is_two) {
                try out.append(.{ .kind = .punct, .text = two });
                i += 2;
                continue;
            }
        }
        try out.append(.{ .kind = .punct, .text = src[i .. i + 1] });
        i += 1;
    }
    try out.append(.{ .kind = .eof, .text = "" });
    return out.toOwnedSlice();
}

const VmComp = struct {
    toks: []VmTok,
    pos: usize = 0,
    code: std.ArrayList(VmIns),
    locals: std.ArrayList([]const u8),
    arr_n: std.ArrayList(u16),
    fns: []VmFn,
    reject: ?[]const u8 = null,

    fn peek(self: *VmComp) VmTok {
        return self.toks[self.pos];
    }

    fn bump(self: *VmComp) VmTok {
        const tk = self.toks[self.pos];
        if (tk.kind != .eof) self.pos += 1;
        return tk;
    }

    fn atPunct(self: *VmComp, t: []const u8) bool {
        const tk = self.toks[self.pos];
        return tk.kind == .punct and std.mem.eql(u8, tk.text, t);
    }

    fn atIdent(self: *VmComp, t: []const u8) bool {
        const tk = self.toks[self.pos];
        return tk.kind == .ident and std.mem.eql(u8, tk.text, t);
    }

    fn acceptPunct(self: *VmComp, t: []const u8) bool {
        if (self.atPunct(t)) {
            _ = self.bump();
            return true;
        }
        return false;
    }

    fn fail(self: *VmComp, code: []const u8) void {
        if (self.reject == null) self.reject = code;
    }

    fn emit(self: *VmComp, op: VmOp, a: i64) !usize {
        try self.code.append(.{ .op = op, .a = a });
        return self.code.items.len - 1;
    }

    fn here(self: *VmComp) i64 {
        const n: i64 = @intCast(self.code.items.len);
        return n;
    }

    fn patch(self: *VmComp, at: usize) void {
        self.code.items[at].a = self.here();
    }

    fn findLocal(self: *VmComp, name: []const u8) ?i64 {
        for (self.locals.items, 0..) |l, idx| {
            if (std.mem.eql(u8, l, name)) {
                const v: i64 = @intCast(idx);
                return v;
            }
        }
        return null;
    }

    fn localIdx(self: *VmComp, name: []const u8) !i64 {
        if (self.findLocal(name)) |v| return v;
        if (self.locals.items.len >= VM_MAX_LOCALS) {
            self.fail("VM_REJ_TOO_MANY_LOCALS");
            return 0;
        }
        try self.locals.append(name);
        try self.arr_n.append(0);
        const v: i64 = @intCast(self.locals.items.len - 1);
        return v;
    }

    fn localArrN(self: *VmComp, li: i64) u16 {
        const idx: usize = @intCast(li);
        if (idx >= self.arr_n.items.len) return 0;
        return self.arr_n.items[idx];
    }

    fn markArr(self: *VmComp, li: i64, n: u16) void {
        const idx: usize = @intCast(li);
        if (idx < self.arr_n.items.len) self.arr_n.items[idx] = n;
    }

    fn findFn(self: *VmComp, name: []const u8) ?i64 {
        for (self.fns, 0..) |f, idx| {
            if (f.sig_ok and std.mem.eql(u8, f.name, name)) {
                const v: i64 = @intCast(idx);
                return v;
            }
        }
        return null;
    }

    fn expr(self: *VmComp) anyerror!void {
        try self.eOr();
    }

    fn eOr(self: *VmComp) anyerror!void {
        try self.eAnd();
        while (self.atPunct("||")) {
            _ = self.bump();
            const j = try self.emit(.jump_if_true_keep, 0);
            _ = try self.emit(.pop, 0);
            try self.eAnd();
            self.patch(j);
        }
    }

    fn eAnd(self: *VmComp) anyerror!void {
        try self.eCmp();
        while (self.atPunct("&&")) {
            _ = self.bump();
            const j = try self.emit(.jump_if_false_keep, 0);
            _ = try self.emit(.pop, 0);
            try self.eCmp();
            self.patch(j);
        }
    }

    fn eCmp(self: *VmComp) anyerror!void {
        try self.eBOr();
        while (true) {
            var op: VmOp = undefined;
            if (self.atPunct("==")) {
                op = .cmp_eq;
            } else if (self.atPunct("!=")) {
                op = .cmp_ne;
            } else if (self.atPunct("<=")) {
                op = .cmp_le;
            } else if (self.atPunct(">=")) {
                op = .cmp_ge;
            } else if (self.atPunct("<")) {
                op = .cmp_lt;
            } else if (self.atPunct(">")) {
                op = .cmp_gt;
            } else return;
            _ = self.bump();
            try self.eBOr();
            _ = try self.emit(op, 0);
        }
    }

    fn eBOr(self: *VmComp) anyerror!void {
        try self.eBXor();
        while (self.atPunct("|")) {
            _ = self.bump();
            try self.eBXor();
            _ = try self.emit(.bit_or, 0);
        }
    }

    fn eBXor(self: *VmComp) anyerror!void {
        try self.eBAnd();
        while (self.atPunct("^")) {
            _ = self.bump();
            try self.eBAnd();
            _ = try self.emit(.bit_xor, 0);
        }
    }

    fn eBAnd(self: *VmComp) anyerror!void {
        try self.eAdd();
        while (self.atPunct("&")) {
            _ = self.bump();
            try self.eAdd();
            _ = try self.emit(.bit_and, 0);
        }
    }

    fn eAdd(self: *VmComp) anyerror!void {
        try self.eMul();
        while (true) {
            if (self.atPunct("+")) {
                _ = self.bump();
                try self.eMul();
                _ = try self.emit(.add, 0);
            } else if (self.atPunct("-")) {
                _ = self.bump();
                try self.eMul();
                _ = try self.emit(.sub, 0);
            } else return;
        }
    }

    fn eMul(self: *VmComp) anyerror!void {
        try self.eUnary();
        while (true) {
            if (self.atPunct("*")) {
                _ = self.bump();
                try self.eUnary();
                _ = try self.emit(.mul, 0);
            } else if (self.atPunct("%")) {
                _ = self.bump();
                try self.eUnary();
                _ = try self.emit(.mod, 0);
            } else if (self.atPunct("/")) {
                self.fail("VM_REJ_INT_DIVISION");
                return;
            } else return;
        }
    }

    fn eUnary(self: *VmComp) anyerror!void {
        if (self.atPunct("~")) {
            _ = self.bump();
            try self.eUnary();
            _ = try self.emit(.bit_not, 0);
            return;
        }
        if (self.atPunct("-")) {
            _ = self.bump();
            try self.eUnary();
            _ = try self.emit(.neg, 0);
            return;
        }
        if (self.atPunct("!")) {
            _ = self.bump();
            try self.eUnary();
            _ = try self.emit(.log_not, 0);
            return;
        }
        try self.ePrimary();
    }

    fn ePrimary(self: *VmComp) anyerror!void {
        const tk = self.peek();
        if (tk.kind == .str) {
            _ = self.bump();
            self.fail("VM_REJ_STRING_LITERAL");
            return;
        }
        if (tk.kind == .number) {
            _ = self.bump();
            const v = std.fmt.parseInt(i64, tk.text, 10) catch {
                self.fail("VM_REJ_LITERAL_RANGE");
                return;
            };
            _ = try self.emit(.push_const, v);
            return;
        }
        if (self.acceptPunct("(")) {
            try self.expr();
            if (!self.acceptPunct(")")) self.fail("VM_REJ_PARSE");
            return;
        }
        if (tk.kind == .ident) {
            _ = self.bump();
            if (std.mem.eql(u8, tk.text, "true")) {
                _ = try self.emit(.push_const, 1);
                return;
            }
            if (std.mem.eql(u8, tk.text, "false")) {
                _ = try self.emit(.push_const, 0);
                return;
            }
            if (self.atPunct("(")) {
                _ = self.bump();
                var argc: usize = 0;
                if (!self.atPunct(")")) {
                    while (true) {
                        try self.expr();
                        argc += 1;
                        if (!self.acceptPunct(",")) break;
                    }
                }
                if (!self.acceptPunct(")")) self.fail("VM_REJ_PARSE");
                if (std.mem.eql(u8, tk.text, "_lia_shl") or std.mem.eql(u8, tk.text, "_lia_shr") or std.mem.eql(u8, tk.text, "_lia_ushr") or std.mem.eql(u8, tk.text, "_lia_mod") or std.mem.eql(u8, tk.text, "@rem")) {
                    if (argc != 2) {
                        self.fail("VM_REJ_ARITY");
                        return;
                    }
                    const op: VmOp = if (std.mem.eql(u8, tk.text, "_lia_shl")) .shl else if (std.mem.eql(u8, tk.text, "_lia_shr")) .shr else if (std.mem.eql(u8, tk.text, "_lia_ushr")) .ushr else .mod;
                    _ = try self.emit(op, 0);
                    return;
                }
                if (self.findFn(tk.text)) |fi| {
                    const idx: usize = @intCast(fi);
                    if (self.fns[idx].nparams != argc) {
                        self.fail("VM_REJ_ARITY");
                        return;
                    }
                    _ = try self.emit(.call, fi);
                    return;
                }
                self.fail("VM_REJ_UNKNOWN_CALL");
                return;
            }
            if (self.atPunct(".")) {
                _ = self.bump();
                const fld = self.peek();
                if (fld.kind == .ident and (std.mem.eql(u8, fld.text, "length") or std.mem.eql(u8, fld.text, "len"))) {
                    _ = self.bump();
                    if (self.findLocal(tk.text)) |li| {
                        if (self.localArrN(li) == 0) {
                            self.fail("VM_REJ_LENGTH_NOT_ARRAY");
                            return;
                        }
                        _ = try self.emit(.arr_len, li);
                        return;
                    }
                    self.fail("VM_REJ_UNBOUND_IDENT");
                    return;
                }
                self.fail("VM_REJ_MEMBER_ACCESS");
                return;
            }
            if (self.atPunct("[")) {
                if (self.findLocal(tk.text)) |li| {
                    if (self.localArrN(li) == 0) {
                        self.fail("VM_REJ_INDEX_NOT_ARRAY");
                        return;
                    }
                    _ = self.bump();
                    try self.expr();
                    if (!self.acceptPunct("]")) self.fail("VM_REJ_PARSE");
                    _ = try self.emit(.load_index, li);
                    return;
                }
                self.fail("VM_REJ_UNBOUND_IDENT");
                return;
            }
            if (self.findLocal(tk.text)) |li| {
                if (self.localArrN(li) > 0) {
                    self.fail("VM_REJ_ARRAY_AS_SCALAR");
                    return;
                }
                _ = try self.emit(.load_local, li);
                return;
            }
            self.fail("VM_REJ_UNBOUND_IDENT");
            return;
        }
        self.fail("VM_REJ_PARSE");
        _ = self.bump();
    }

    fn emitArrLit(self: *VmComp, li: i64, cap: u16) anyerror!void {
        if (!self.acceptPunct("[")) {
            self.fail("VM_REJ_PARSE");
            return;
        }
        var ei: i64 = 0;
        if (!self.atPunct("]")) {
            while (true) {
                if (ei >= cap) {
                    self.fail("VM_REJ_ARRAY_LIT_LEN");
                    return;
                }
                _ = try self.emit(.push_const, ei);
                try self.expr();
                _ = try self.emit(.store_index, li);
                ei += 1;
                if (!self.acceptPunct(",")) break;
            }
        }
        if (!self.acceptPunct("]")) self.fail("VM_REJ_PARSE");
    }

    fn assign(self: *VmComp) anyerror!void {
        const tk = self.peek();
        if (tk.kind != .ident) {
            self.fail("VM_REJ_UNSUPPORTED_STMT");
            return;
        }
        _ = self.bump();
        if (self.atPunct("[")) {
            if (self.findLocal(tk.text)) |li| {
                if (self.localArrN(li) == 0) {
                    self.fail("VM_REJ_INDEX_NOT_ARRAY");
                    return;
                }
                _ = self.bump();
                try self.expr();
                if (!self.acceptPunct("]")) {
                    self.fail("VM_REJ_PARSE");
                    return;
                }
                if (!self.acceptPunct("=")) {
                    self.fail("VM_REJ_UNSUPPORTED_STMT");
                    return;
                }
                try self.expr();
                _ = try self.emit(.store_index, li);
                return;
            }
            self.fail("VM_REJ_UNBOUND_IDENT");
            return;
        }
        if (self.acceptPunct(":")) {
            if (!self.acceptPunct("[")) {
                self.fail("VM_REJ_PARSE");
                return;
            }
            const ntk = self.peek();
            if (ntk.kind != .number) {
                self.fail("VM_REJ_PARSE");
                return;
            }
            _ = self.bump();
            const nval = std.fmt.parseInt(u16, ntk.text, 10) catch {
                self.fail("VM_REJ_ARRAY_TOO_LARGE");
                return;
            };
            if (nval < 1 or nval > VM_MAX_ARR_LEN) {
                self.fail("VM_REJ_ARRAY_TOO_LARGE");
                return;
            }
            if (!self.acceptPunct("]")) {
                self.fail("VM_REJ_PARSE");
                return;
            }
            if (!(self.atIdent("int") or self.atIdent("i64"))) {
                self.fail("VM_REJ_ARRAY_ELEM_NOT_INT");
                return;
            }
            _ = self.bump();
            const li = try self.localIdx(tk.text);
            self.markArr(li, nval);
            if (self.acceptPunct("=")) {
                try self.emitArrLit(li, nval);
            }
            return;
        }
        if (!self.acceptPunct("=")) {
            self.fail("VM_REJ_UNSUPPORTED_STMT");
            return;
        }
        if (self.atPunct("[")) {
            const li = try self.localIdx(tk.text);
            const cap = self.localArrN(li);
            if (cap == 0) {
                self.fail("VM_REJ_INDEX_NOT_ARRAY");
                return;
            }
            try self.emitArrLit(li, cap);
            return;
        }
        try self.expr();
        const li = try self.localIdx(tk.text);
        if (self.localArrN(li) > 0) {
            self.fail("VM_REJ_ARRAY_AS_SCALAR");
            return;
        }
        _ = try self.emit(.store_local, li);
    }

    fn block(self: *VmComp) anyerror!void {
        if (!self.acceptPunct("{")) {
            self.fail("VM_REJ_PARSE");
            return;
        }
        while (!self.atPunct("}")) {
            if (self.reject != null) return;
            if (self.peek().kind == .eof) {
                self.fail("VM_REJ_PARSE");
                return;
            }
            try self.stmt();
        }
        _ = self.bump();
    }

    fn ifChain(self: *VmComp, ends: *std.ArrayList(usize)) anyerror!void {
        if (!self.acceptPunct("(")) {
            self.fail("VM_REJ_PARSE");
            return;
        }
        try self.expr();
        if (!self.acceptPunct(")")) {
            self.fail("VM_REJ_PARSE");
            return;
        }
        const jf = try self.emit(.jump_if_false, 0);
        try self.block();
        if (self.reject != null) return;
        const je = try self.emit(.jump, 0);
        try ends.append(je);
        self.patch(jf);
        if (self.acceptPunct(":")) {
            if (self.atPunct("(")) {
                try self.ifChain(ends);
                return;
            }
            try self.block();
            return;
        }
        if (self.atIdent("else")) {
            _ = self.bump();
            if (self.atIdent("if")) {
                _ = self.bump();
                try self.ifChain(ends);
                return;
            }
            try self.block();
            return;
        }
    }

    fn stmt(self: *VmComp) anyerror!void {
        if (self.acceptPunct(";")) return;
        if (self.atPunct("^")) {
            _ = self.bump();
            try self.expr();
            _ = self.acceptPunct(";");
            _ = try self.emit(.ret, 0);
            return;
        }
        if (self.atIdent("return")) {
            _ = self.bump();
            try self.expr();
            _ = self.acceptPunct(";");
            _ = try self.emit(.ret, 0);
            return;
        }
        if (self.atPunct("?") or self.atIdent("if")) {
            _ = self.bump();
            var ends = std.ArrayList(usize).init(self.code.allocator);
            try self.ifChain(&ends);
            if (self.reject != null) return;
            for (ends.items) |e| self.patch(e);
            _ = self.acceptPunct(";");
            return;
        }
        if (self.atIdent("while")) {
            _ = self.bump();
            const top = self.here();
            if (!self.acceptPunct("(")) {
                self.fail("VM_REJ_PARSE");
                return;
            }
            try self.expr();
            if (!self.acceptPunct(")")) {
                self.fail("VM_REJ_PARSE");
                return;
            }
            const jf = try self.emit(.jump_if_false, 0);
            try self.block();
            if (self.reject != null) return;
            _ = try self.emit(.jump, top);
            self.patch(jf);
            _ = self.acceptPunct(";");
            return;
        }
        if (self.atPunct("#")) {
            self.fail("VM_REJ_FOR_LOOP");
            return;
        }
        try self.assign();
        if (self.reject != null) return;
        if (!self.acceptPunct(";")) self.fail("VM_REJ_PARSE");
    }
};

fn vmArrLenOf(ty: []const u8) ?u16 {
    const t = std.mem.trim(u8, ty, " \t\r\n");
    if (t.len < 6 or t[0] != '[') return null;
    const close = std.mem.indexOfScalar(u8, t, ']') orelse return null;
    const num = std.mem.trim(u8, t[1..close], " \t");
    const n = std.fmt.parseInt(u16, num, 10) catch return null;
    const rest = std.mem.trim(u8, t[close + 1 ..], " \t");
    if (!(std.mem.eql(u8, rest, "int") or std.mem.eql(u8, rest, "i64"))) return null;
    return n;
}

fn vmSigEligible(info: FnTypeInfo) ?[]const u8 {
    if (!std.mem.eql(u8, info.return_type, "int") and !std.mem.eql(u8, info.return_type, "i64")) return "VM_REJ_RETURN_NOT_INT";
    for (info.params) |p| {
        if (std.mem.eql(u8, p.type_name, "int") or std.mem.eql(u8, p.type_name, "i64")) continue;
        if (vmArrLenOf(p.type_name)) |n| {
            if (n < 1 or n > VM_MAX_ARR_LEN) return "VM_REJ_ARRAY_TOO_LARGE";
            continue;
        }
        return "VM_REJ_PARAM_NOT_INT";
    }
    return null;
}

fn vmResolveDeps(fns: []VmFn) void {
    var changed = true;
    while (changed) {
        changed = false;
        for (fns) |*f| {
            if (!f.ok) continue;
            for (f.code) |ins| {
                if (ins.op != .call) continue;
                const ti: usize = @intCast(ins.a);
                if (ti >= fns.len or !fns[ti].ok) {
                    f.ok = false;
                    f.reject = "VM_REJ_DEP_REJECTED";
                    changed = true;
                    break;
                }
            }
        }
    }
}

pub fn vmBuild(allocator: std.mem.Allocator, src: []const u8) !VmModule {
    const infos = try parse_fn_type_infos(allocator, src);
    var fns = try allocator.alloc(VmFn, infos.len);
    for (infos, 0..) |info, idx| {
        fns[idx] = .{ .name = info.name, .nparams = info.params.len };
        if (vmSigEligible(info)) |code| {
            fns[idx].reject = code;
        } else {
            fns[idx].sig_ok = true;
        }
    }
    for (infos, 0..) |info, idx| {
        if (!fns[idx].sig_ok) continue;
        var comp = VmComp{
            .toks = try vmTokenize(allocator, info.body),
            .code = std.ArrayList(VmIns).init(allocator),
            .locals = std.ArrayList([]const u8).init(allocator),
            .arr_n = std.ArrayList(u16).init(allocator),
            .fns = fns,
        };
        for (info.params) |p| {
            const li = try comp.localIdx(p.name);
            if (vmArrLenOf(p.type_name)) |n| {
                if (n < 1 or n > VM_MAX_ARR_LEN) {
                    fns[idx].reject = "VM_REJ_ARRAY_TOO_LARGE";
                    fns[idx].sig_ok = false;
                    break;
                }
                comp.markArr(li, n);
            }
        }
        if (!fns[idx].sig_ok) continue;
        while (comp.peek().kind != .eof and comp.reject == null) {
            try comp.stmt();
        }
        if (comp.reject) |code| {
            fns[idx].reject = code;
            continue;
        }
        _ = try comp.emit(.push_const, 0);
        _ = try comp.emit(.ret, 0);
        fns[idx].code = try comp.code.toOwnedSlice();
        fns[idx].nlocals = comp.locals.items.len;
        fns[idx].arr_n = try comp.arr_n.toOwnedSlice();
        fns[idx].ok = true;
    }
    vmResolveDeps(fns);
    return .{ .fns = fns };
}

pub fn vmFind(mod: *const VmModule, name: []const u8) ?usize {
    for (mod.fns, 0..) |f, idx| {
        if (std.mem.eql(u8, f.name, name)) return idx;
    }
    return null;
}

fn vmShift(a: i64, b: i64, left: bool) i64 {
    if (b < 0 or b >= 64) return 0;
    const shift: u6 = @as(u6, @truncate(@as(u64, @intCast(b))));
    if (left) {
        const ua: u64 = @bitCast(a);
        return @bitCast(ua << shift);
    }
    return a >> shift;
}

fn vmShiftU(a: i64, b: i64) i64 {
    if (b < 0 or b >= 64) return 0;
    const shift: u6 = @as(u6, @truncate(@as(u64, @intCast(b))));
    return @bitCast(@as(u64, @bitCast(a)) >> shift);
}

pub fn vmExec(mod: *const VmModule, fi: usize, args: []const i64, depth: usize, steps: *u64) VmError!i64 {
    if (depth > VM_MAX_DEPTH) return error.VmDepth;
    if (fi >= mod.fns.len) return error.VmBadFunction;
    const f = &mod.fns[fi];
    if (!f.ok) return error.VmBadFunction;
    if (args.len != f.nparams) return error.VmArity;
    var locals = [_]i64{0} ** VM_MAX_LOCALS;
    var pool: [VM_MAX_ARRS][VM_MAX_ARR_LEN]i64 = undefined;
    var pool_len = [_]u16{0} ** VM_MAX_ARRS;
    var pool_used: usize = 0;
    if (f.arr_n.len > 0) {
        for (f.arr_n, 0..) |an, li| {
            if (an == 0) continue;
            if (pool_used >= VM_MAX_ARRS) return error.VmBadFunction;
            const slot = pool_used;
            pool_used += 1;
            pool_len[slot] = an;
            var z: usize = 0;
            while (z < an) : (z += 1) pool[slot][z] = 0;
            locals[li] = @intCast(slot);
        }
    }
    for (args, 0..) |a, idx| {
        if (idx < f.arr_n.len and f.arr_n[idx] > 0) continue;
        locals[idx] = a;
    }
    var stack = [_]i64{0} ** VM_MAX_STACK;
    var sp: usize = 0;
    var pc: usize = 0;
    while (pc < f.code.len) {
        steps.* += 1;
        if (steps.* > VM_STEP_LIMIT) return error.VmStepLimit;
        const ins = f.code[pc];
        pc += 1;
        switch (ins.op) {
            .push_const => {
                if (sp >= VM_MAX_STACK) return error.VmStackOverflow;
                stack[sp] = ins.a;
                sp += 1;
            },
            .load_local => {
                if (sp >= VM_MAX_STACK) return error.VmStackOverflow;
                const li: usize = @intCast(ins.a);
                stack[sp] = locals[li];
                sp += 1;
            },
            .store_local => {
                if (sp == 0) return error.VmStackUnderflow;
                sp -= 1;
                const li: usize = @intCast(ins.a);
                locals[li] = stack[sp];
            },
            .pop => {
                if (sp == 0) return error.VmStackUnderflow;
                sp -= 1;
            },
            .bit_not => {
                if (sp == 0) return error.VmStackUnderflow;
                stack[sp - 1] = ~stack[sp - 1];
            },
            .neg => {
                if (sp == 0) return error.VmStackUnderflow;
                stack[sp - 1] = 0 -% stack[sp - 1];
            },
            .log_not => {
                if (sp == 0) return error.VmStackUnderflow;
                stack[sp - 1] = if (stack[sp - 1] == 0) 1 else 0;
            },
            .jump => {
                pc = @intCast(ins.a);
            },
            .jump_if_false => {
                if (sp == 0) return error.VmStackUnderflow;
                sp -= 1;
                if (stack[sp] == 0) pc = @intCast(ins.a);
            },
            .jump_if_false_keep => {
                if (sp == 0) return error.VmStackUnderflow;
                if (stack[sp - 1] == 0) pc = @intCast(ins.a);
            },
            .jump_if_true_keep => {
                if (sp == 0) return error.VmStackUnderflow;
                if (stack[sp - 1] != 0) pc = @intCast(ins.a);
            },
            .ret => {
                if (sp == 0) return error.VmStackUnderflow;
                return stack[sp - 1];
            },
            .load_index => {
                if (sp == 0) return error.VmStackUnderflow;
                sp -= 1;
                const ix = stack[sp];
                const li: usize = @intCast(ins.a);
                const slot: usize = @intCast(locals[li]);
                var v: i64 = 0;
                if (slot < VM_MAX_ARRS) {
                    const n = pool_len[slot];
                    if (ix >= 0 and ix < @as(i64, n)) {
                        v = pool[slot][@as(usize, @intCast(ix))];
                    }
                }
                if (sp >= VM_MAX_STACK) return error.VmStackOverflow;
                stack[sp] = v;
                sp += 1;
            },
            .store_index => {
                if (sp < 2) return error.VmStackUnderflow;
                sp -= 2;
                const ix = stack[sp];
                const val = stack[sp + 1];
                const li: usize = @intCast(ins.a);
                const slot: usize = @intCast(locals[li]);
                if (slot < VM_MAX_ARRS) {
                    const n = pool_len[slot];
                    if (ix >= 0 and ix < @as(i64, n)) {
                        pool[slot][@as(usize, @intCast(ix))] = val;
                    }
                }
            },
            .arr_len => {
                if (sp >= VM_MAX_STACK) return error.VmStackOverflow;
                const li: usize = @intCast(ins.a);
                const slot: usize = @intCast(locals[li]);
                var n: i64 = 0;
                if (slot < VM_MAX_ARRS) n = @as(i64, pool_len[slot]);
                stack[sp] = n;
                sp += 1;
            },
            .call => {
                const ti: usize = @intCast(ins.a);
                if (ti >= mod.fns.len) return error.VmBadFunction;
                const n = mod.fns[ti].nparams;
                if (sp < n) return error.VmStackUnderflow;
                sp -= n;
                const r = try vmExec(mod, ti, stack[sp .. sp + n], depth + 1, steps);
                stack[sp] = r;
                sp += 1;
            },
            else => {
                if (sp < 2) return error.VmStackUnderflow;
                sp -= 2;
                const x = stack[sp];
                const y = stack[sp + 1];
                var r: i64 = 0;
                switch (ins.op) {
                    .add => r = x +% y,
                    .sub => r = x -% y,
                    .mul => r = x *% y,
                    .mod => r = if (y == 0) 0 else @rem(x, y),
                    .bit_and => r = x & y,
                    .bit_or => r = x | y,
                    .bit_xor => r = x ^ y,
                    .shl => r = vmShift(x, y, true),
                    .shr => r = vmShift(x, y, false),
                    .ushr => r = vmShiftU(x, y),
                    .cmp_eq => r = if (x == y) 1 else 0,
                    .cmp_ne => r = if (x != y) 1 else 0,
                    .cmp_lt => r = if (x < y) 1 else 0,
                    .cmp_gt => r = if (x > y) 1 else 0,
                    .cmp_le => r = if (x <= y) 1 else 0,
                    .cmp_ge => r = if (x >= y) 1 else 0,
                    else => return error.VmBadFunction,
                }
                stack[sp] = r;
                sp += 1;
            },
        }
    }
    return 0;
}

const FnStructuralClass = enum {
    gf2_linear,
    gf2_affine,
    gf2_parametric_shift,
    bitwise_independent,
    non_linear_or_carry,
};

fn classifyFnByOpcodes(f: *const VmFn) FnStructuralClass {
    for (f.code) |ins| {
        switch (ins.op) {
            .add, .sub, .mul, .mod => return .non_linear_or_carry,
            .jump, .jump_if_false, .jump_if_false_keep, .jump_if_true_keep => return .non_linear_or_carry,
            .cmp_eq, .cmp_ne, .cmp_lt, .cmp_gt, .cmp_le, .cmp_ge => return .non_linear_or_carry,
            else => {},
        }
    }

    if (f.nparams == 1) {
        return .gf2_linear;
    }
    if (f.nparams == 2) {
        return .gf2_parametric_shift;
    }
    if (f.nparams == 3) {
        return .bitwise_independent;
    }

    return .non_linear_or_carry;
}

pub fn vmVerifyFile(allocator: std.mem.Allocator, src: []const u8) !void {
    const stdout = std.io.getStdOut().writer();
    const mod = try vmBuild(allocator, src);
    try stdout.print("@RULEL:LIN_VERIFY:1.0.0\n", .{});
    try stdout.print(".engine=\"Opcode Inspector + GF(2) Linear/Affine Probe Verifier (LinVM)\"\n", .{});
    try stdout.print(".results{{\n", .{});
    var proved_count: usize = 0;
    var unproven_count: usize = 0;
    var rejected_count: usize = 0;

    const probe_vectors = [_]i64{
        3, 5, 6, 7, 9, 10, 12, 15, 27, 42,
        0x55555555, 0xAAAAAAAA, 0x12345678,
        0x7FFFFFFF, 0xFFFFFFFF, 0x0F0F0F0F, 0xF0F0F0F0,
    };

    for (mod.fns) |f| {
        if (!f.ok) {
            try stdout.print("  .{s}{{ status=REJECTED reason=\"{s}\" }}\n", .{ f.name, f.reject });
            rejected_count += 1;
            continue;
        }

        const structural_class = classifyFnByOpcodes(&f);

        if (structural_class == .non_linear_or_carry) {
            try stdout.print("  .{s}{{ status=REQUIRES_EXHAUSTIVE_OR_SOLVER reason=\"contains_carry_arithmetic_or_branches\" }}\n", .{f.name});
            unproven_count += 1;
            continue;
        }

        const fi = vmFind(&mod, f.name).?;

        if (f.nparams == 1) {
            var steps: u64 = 0;
            const args_zero = [_]i64{0};
            const c = vmExec(&mod, fi, &args_zero, 0, &steps) catch {
                try stdout.print("  .{s}{{ status=REQUIRES_EXHAUSTIVE_OR_SOLVER reason=\"vm_exec_fault\" }}\n", .{f.name});
                unproven_count += 1;
                continue;
            };

            var L = [_]i64{0} ** 32;
            var basis_ok = true;
            var k: u6 = 0;
            while (k < 32) : (k += 1) {
                const e_k: i64 = @as(i64, 1) << k;
                const args_k = [_]i64{e_k};
                var call_steps: u64 = 0;
                const out_k = vmExec(&mod, fi, &args_k, 0, &call_steps) catch {
                    basis_ok = false;
                    break;
                };
                L[k] = out_k ^ c;
            }

            if (!basis_ok) {
                try stdout.print("  .{s}{{ status=REQUIRES_EXHAUSTIVE_OR_SOLVER reason=\"basis_eval_failed\" }}\n", .{f.name});
                unproven_count += 1;
                continue;
            }

            var probes_ok = true;
            for (probe_vectors) |probe_val| {
                var expected = c;
                var bit_idx: u6 = 0;
                while (bit_idx < 32) : (bit_idx += 1) {
                    if ((probe_val & (@as(i64, 1) << bit_idx)) != 0) {
                        expected ^= L[bit_idx];
                    }
                }
                const probe_args = [_]i64{probe_val};
                var call_steps: u64 = 0;
                const actual = vmExec(&mod, fi, &probe_args, 0, &call_steps) catch {
                    probes_ok = false;
                    break;
                };
                if (actual != expected) {
                    probes_ok = false;
                    break;
                }
            }

            if (probes_ok) {
                if (c == 0) {
                    try stdout.print("  .{s}{{ status=PROVED_STRUCTURAL class=\"GF2_LINEAR\" basis_cases=32 probes={d} total_domain=\"2^32 (4294967296)\" }}\n", .{ f.name, probe_vectors.len });
                } else {
                    try stdout.print("  .{s}{{ status=PROVED_STRUCTURAL class=\"GF2_AFFINE\" basis_cases=33 probes={d} total_domain=\"2^32 (4294967296)\" }}\n", .{ f.name, probe_vectors.len });
                }
                proved_count += 1;
                continue;
            } else {
                try stdout.print("  .{s}{{ status=REQUIRES_EXHAUSTIVE_OR_SOLVER reason=\"probe_divergence_from_linear_basis\" }}\n", .{f.name});
                unproven_count += 1;
                continue;
            }
        }

        if (f.nparams == 3) {
            var bitwise_ok = true;
            var tt = [_][8]i64{[_]i64{0} ** 8} ** 32;
            var b: u6 = 0;
            while (b < 32) : (b += 1) {
                var combo: u8 = 0;
                while (combo < 8) : (combo += 1) {
                    const x: i64 = if ((combo & 1) != 0) @as(i64, 1) << b else 0;
                    const y: i64 = if ((combo & 2) != 0) @as(i64, 1) << b else 0;
                    const z: i64 = if ((combo & 4) != 0) @as(i64, 1) << b else 0;
                    const args = [_]i64{ x, y, z };
                    var call_steps: u64 = 0;
                    const res = vmExec(&mod, fi, &args, 0, &call_steps) catch {
                        bitwise_ok = false;
                        break;
                    };
                    tt[b][combo] = res;
                }
                if (!bitwise_ok) break;
            }

            if (!bitwise_ok) {
                try stdout.print("  .{s}{{ status=REQUIRES_EXHAUSTIVE_OR_SOLVER reason=\"truth_table_eval_failed\" }}\n", .{f.name});
                unproven_count += 1;
                continue;
            }

            const cross_probes = [_][3]i64{
                .{ 0x55555555, 0xAAAAAAAA, 0x0F0F0F0F },
                .{ 0x12345678, 0x87654321, 0xFFFFFFFF },
                .{ 0, 0xFFFFFFFF, 0x55555555 },
                .{ 0x7FFFFFFF, 0, 0xAAAAAAAA },
            };

            for (cross_probes) |cp| {
                var expected: i64 = 0;
                var bit_idx: u6 = 0;
                while (bit_idx < 32) : (bit_idx += 1) {
                    const bx: u8 = if ((cp[0] & (@as(i64, 1) << bit_idx)) != 0) 1 else 0;
                    const by: u8 = if ((cp[1] & (@as(i64, 1) << bit_idx)) != 0) 2 else 0;
                    const bz: u8 = if ((cp[2] & (@as(i64, 1) << bit_idx)) != 0) 4 else 0;
                    const combo = bx | by | bz;
                    expected |= tt[bit_idx][combo];
                }
                const cp_args = [_]i64{ cp[0], cp[1], cp[2] };
                var call_steps: u64 = 0;
                const actual = vmExec(&mod, fi, &cp_args, 0, &call_steps) catch {
                    bitwise_ok = false;
                    break;
                };
                if (actual != expected) {
                    bitwise_ok = false;
                    break;
                }
            }

            if (bitwise_ok) {
                try stdout.print("  .{s}{{ status=PROVED_STRUCTURAL class=\"BITWISE_INDEPENDENT\" truth_table_cases=256 probes={d} total_domain=\"2^96\" }}\n", .{ f.name, cross_probes.len });
                proved_count += 1;
                continue;
            } else {
                try stdout.print("  .{s}{{ status=REQUIRES_EXHAUSTIVE_OR_SOLVER reason=\"cross_bit_dependency_detected\" }}\n", .{f.name});
                unproven_count += 1;
                continue;
            }
        }

        if (f.nparams == 2) {
            var shift_ok = true;
            const shift_amounts = [_]i64{ 0, 1, 2, 7, 8, 15, 16, 31, -1, 32, 64 };
            for (shift_amounts) |n_shift| {
                var L_shift = [_]i64{0} ** 32;
                var k: u6 = 0;
                while (k < 32) : (k += 1) {
                    const e_k: i64 = @as(i64, 1) << k;
                    const args = [_]i64{ e_k, n_shift };
                    var call_steps: u64 = 0;
                    L_shift[k] = vmExec(&mod, fi, &args, 0, &call_steps) catch {
                        shift_ok = false;
                        break;
                    };
                }
                if (!shift_ok) break;

                for (probe_vectors[0..5]) |pv| {
                    var expected: i64 = 0;
                    var bit_idx: u6 = 0;
                    while (bit_idx < 32) : (bit_idx += 1) {
                        if ((pv & (@as(i64, 1) << bit_idx)) != 0) {
                            expected ^= L_shift[bit_idx];
                        }
                    }
                    const args = [_]i64{ pv, n_shift };
                    var call_steps: u64 = 0;
                    const actual = vmExec(&mod, fi, &args, 0, &call_steps) catch {
                        shift_ok = false;
                        break;
                    };
                    if (actual != expected) {
                        shift_ok = false;
                        break;
                    }
                }
                if (!shift_ok) break;
            }

            if (shift_ok) {
                try stdout.print("  .{s}{{ status=PROVED_STRUCTURAL class=\"GF2_PARAMETRIC_SHIFT\" cases=1024 probes=55 total_domain=\"2^37\" }}\n", .{f.name});
                proved_count += 1;
                continue;
            } else {
                try stdout.print("  .{s}{{ status=REQUIRES_EXHAUSTIVE_OR_SOLVER reason=\"shift_probe_divergence\" }}\n", .{f.name});
                unproven_count += 1;
                continue;
            }
        }

        try stdout.print("  .{s}{{ status=REQUIRES_EXHAUSTIVE_OR_SOLVER reason=\"unsupported_aridade\" }}\n", .{f.name});
        unproven_count += 1;
    }

    try stdout.print("}}\n.summary{{ proved_structural={d} unproven={d} rejected={d} }}\n", .{ proved_count, unproven_count, rejected_count });
}

// LIN-HOST-END

fn argEq(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}

fn endsLin(name: []const u8) bool {
    if (std.mem.endsWith(u8, name, ".test.lin") or std.mem.eql(u8, name, "run_all.lin")) return false;
    return name.len >= 4 and std.mem.endsWith(u8, name, ".lin");
}

fn apply_dynamic_rules_if_present(allocator: std.mem.Allocator, src: []const u8) []const u8 {
    const rules_file = std.fs.cwd().openFile("storage/dynamic_rules.rulel", .{}) catch return src;
    rules_file.close();

    const rules_content = std.fs.cwd().readFileAlloc(allocator, "storage/dynamic_rules.rulel", 1024 * 1024) catch return src;
    defer allocator.free(rules_content);
    if (std.mem.indexOf(u8, rules_content, "RULE_TERNARY_R17_CANONICAL_LAZY") == null) {
        return src;
    }

    var s: []const u8 = src;
    var iterations: usize = 0;
    while (iterations < 100) : (iterations += 1) {
        var changed = false;
        var i: usize = 0;
        while (i < s.len) : (i += 1) {
            const is_ret = (s[i] == '^' and i + 1 < s.len and s[i + 1] == '(');
            const sp: ?usize = if (is_ret) i + 1 else if (s[i] == '(') i else null;
            if (sp) |start_p| {
                var depth: i64 = 0;
                var close_p: ?usize = null;
                var j: usize = start_p;
                while (j < s.len) : (j += 1) {
                    if (s[j] == '(') depth += 1
                    else if (s[j] == ')') {
                        depth -= 1;
                        if (depth == 0) { close_p = j; break; }
                    }
                }
                if (close_p) |cp| {
                    const inside = s[start_p + 1 .. cp];
                    var pdepth: i64 = 0;
                    var q_idx: ?usize = null;
                    var c_idx: ?usize = null;
                    var k: usize = 0;
                    while (k < inside.len) : (k += 1) {
                        if (inside[k] == '(') pdepth += 1
                        else if (inside[k] == ')') pdepth -= 1
                        else if (pdepth == 0) {
                            if (q_idx == null and k + 2 < inside.len and inside[k] == ' ' and inside[k + 1] == '?' and inside[k + 2] == ' ') {
                                q_idx = k;
                            } else if (q_idx != null and c_idx == null and k + 2 < inside.len and inside[k] == ' ' and inside[k + 1] == ':' and inside[k + 2] == ' ') {
                                c_idx = k;
                            }
                        }
                    }
                    if (q_idx != null and c_idx != null) {
                        const raw_cond = std.mem.trim(u8, inside[0..q_idx.?], " \t\r\n");
                        const val_a = std.mem.trim(u8, inside[q_idx.? + 3 .. c_idx.?], " \t\r\n");
                        const val_b = std.mem.trim(u8, inside[c_idx.? + 3 ..], " \t\r\n");

                        const has_cmp = (std.mem.indexOf(u8, raw_cond, "==") != null or std.mem.indexOf(u8, raw_cond, "!=") != null or std.mem.indexOf(u8, raw_cond, "<") != null or std.mem.indexOf(u8, raw_cond, ">") != null);
                        const cond = if (has_cmp) raw_cond else (std.fmt.allocPrint(allocator, "(({s}) != 0)", .{raw_cond}) catch raw_cond);

                        var repl = std.ArrayList(u8).init(allocator);
                        defer repl.deinit();
                        if (is_ret) {
                            repl.writer().print("?({s}){{ ^{s} }} : {{ ^{s} }}", .{ cond, val_a, val_b }) catch {};
                        } else {
                            repl.writer().print("(if ({s}) {s} else {s})", .{ cond, val_a, val_b }) catch {};
                        }

                        const prefix = s[0..i];
                        const suffix = s[cp + 1 ..];
                        s = std.mem.concat(allocator, u8, &.{ prefix, repl.items, suffix }) catch s;
                        changed = true;
                        break;
                    } else if (std.mem.indexOf(u8, rules_content, "RULE_COALESCE_R20_PROMOTED_FALLBACK") != null and std.mem.indexOf(u8, inside, " ?? ") != null) {
                        const qq_pos = std.mem.indexOf(u8, inside, " ?? ").?;
                        const val_a = std.mem.trim(u8, inside[0..qq_pos], " \t\r\n");
                        const val_b = std.mem.trim(u8, inside[qq_pos + 4 ..], " \t\r\n");

                        var repl = std.ArrayList(u8).init(allocator);
                        defer repl.deinit();
                        if (is_ret) {
                            repl.writer().print("?({s} != -1){{ ^{s} }} : {{ ^{s} }}", .{ val_a, val_a, val_b }) catch {};
                        } else {
                            repl.writer().print("(if ({s} != -1) {s} else {s})", .{ val_a, val_a, val_b }) catch {};
                        }

                        const prefix = s[0..i];
                        const suffix = s[cp + 1 ..];
                        s = std.mem.concat(allocator, u8, &.{ prefix, repl.items, suffix }) catch s;
                        changed = true;
                        break;
                    }
                }
            }
        }
        if (!changed) break;
    }
    return s;
}

fn runLinTestFile(path: []const u8) !std.process.Child.RunResult {
    const raw_src = try std.fs.cwd().readFileAlloc(LIA_ALLOC, path, 10 * 1024 * 1024);
    defer LIA_ALLOC.free(raw_src);
    const src = apply_dynamic_rules_if_present(LIA_ALLOC, raw_src);
    if (lin_valid_strict(src) == 0) return error.LinParse;
    const names = lin_check(src);
    const fns = lin_to_zig(src);
    const host = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin.zig", 10 * 1024 * 1024);
    defer LIA_ALLOC.free(host);
    const m_fn = std.mem.indexOf(u8, host, "\npub fn slice2(") orelse return error.MissingRuntime;
    var main_body = std.ArrayList(u8).init(LIA_ALLOC);
    defer main_body.deinit();
    const mw = main_body.writer();
    try mw.writeAll("pub fn main() !void {\n    LIA_ALLOC = std.heap.page_allocator;\n    var fails: i64 = 0;\n");
    var it = std.mem.splitScalar(u8, names, ',');
    var ntests: i64 = 0;
    while (it.next()) |raw| {
        const name = std.mem.trim(u8, raw, " \t");
        if (name.len >= 5 and std.mem.startsWith(u8, name, "test_")) {
            ntests += 1;
            try mw.print("    if ({s}() != 1) {{ fails += 1; std.debug.print(\"FAIL {s}\\n\", .{{}}); }}\n", .{ name, name });
        }
    }
    try mw.writeAll("    if (fails != 0) std.process.exit(1);\n    std.debug.print(\"ok ");
    try mw.print("{d}", .{ntests});
    try mw.writeAll("\\n\", .{});\n}\n");
    const zig_src = try std.mem.concat(LIA_ALLOC, u8, &.{ host[0..m_fn], "\n", fns, "\n", main_body.items });
    defer LIA_ALLOC.free(zig_src);
    const tmp_path = "src/lin_test_run.zig";
    const tf = try std.fs.cwd().createFile(tmp_path, .{});
    defer tf.close();
    try tf.writeAll(zig_src);
    var zb: []const u8 = "zig";
    if (std.fs.openFileAbsolute("/home/k/.local/bin/zig", .{})) |zf| {
        zf.close();
        zb = "/home/k/.local/bin/zig";
    } else |_| {}
    return std.process.Child.run(.{
        .allocator = LIA_ALLOC,
        .argv = &.{ zb, "run", "-O", "ReleaseFast", tmp_path },
        .max_output_bytes = 1024 * 1024,
    });
}

const ZIG_RUNTIME_PRELUDE =
    \\const std = @import("std");
    \\pub var LIA_ALLOC: std.mem.Allocator = undefined;
    \\fn _lia_str(x: anytype) []const u8 {
    \\    const T = @TypeOf(x);
    \\    switch (@typeInfo(T)) {
    \\        .Pointer => |p| {
    \\            if (p.size == .Slice and p.child == u8) return x;
    \\            if (p.size == .One) {
    \\                switch (@typeInfo(p.child)) {
    \\                    .Array => |a| { if (a.child == u8) return x[0..]; },
    \\                    else => {},
    \\                }
    \\            }
    \\        },
    \\        .Bool => return if (x) "true" else "false",
    \\        .Int, .ComptimeInt => return std.fmt.allocPrint(LIA_ALLOC, "{d}", .{x}) catch "",
    \\        .Float, .ComptimeFloat => return std.fmt.allocPrint(LIA_ALLOC, "{d}", .{x}) catch "",
    \\        else => {},
    \\    }
    \\    return "";
    \\}
    \\pub fn _lia_cat(a: anytype, b: anytype) []const u8 {
    \\    return std.mem.concat(LIA_ALLOC, u8, &.{ _lia_str(a), _lia_str(b) }) catch "";
    \\}
    \\fn _lia_char_at(s: []const u8, i: i64) []const u8 {
    \\    if (i < 0) return "";
    \\    const idx = @as(usize, @intCast(i));
    \\    if (idx < s.len) return s[idx .. idx + 1];
    \\    return "";
    \\}
    \\fn _lia_char_code_at(s: []const u8, i: i64) i64 {
    \\    if (i < 0) return 0;
    \\    const idx = @as(usize, @intCast(i));
    \\    if (idx < s.len) return @as(i64, s[idx]);
    \\    return 0;
    \\}
    \\fn _lia_from_code(c: i64) []const u8 {
    \\    var buf: [1]u8 = .{@as(u8, @truncate(@as(u64, @intCast(c))))};
    \\    return std.fmt.allocPrint(LIA_ALLOC, "{s}", .{buf[0..]}) catch "";
    \\}
    \\fn _lia_slice(s: []const u8, a: i64, b: i64) []const u8 {
    \\    if (a < 0 or b < 0) return "";
    \\    var start = @as(usize, @intCast(a));
    \\    var end = @as(usize, @intCast(b));
    \\    if (start > s.len) start = s.len;
    \\    if (end > s.len) end = s.len;
    \\    if (start >= end) return "";
    \\    return s[start..end];
    \\}
    \\fn _lia_idx(a: i64) usize {
    \\    return @as(usize, @intCast(a));
    \\}
    \\fn _lia_shl(a: i64, b: i64) i64 {
    \\    if (b < 0 or b >= 64) return 0;
    \\    const shift: u6 = @as(u6, @truncate(@as(u64, @intCast(b))));
    \\    const ua: u64 = @bitCast(a);
    \\    return @bitCast(ua << shift);
    \\}
    \\fn _lia_shr(a: i64, b: i64) i64 {
    \\    if (b < 0 or b >= 64) return 0;
    \\    const shift: u6 = @as(u6, @truncate(@as(u64, @intCast(b))));
    \\    return a >> shift;
    \\}
    \\fn _lia_ushr(a: i64, b: i64) i64 {
    \\    if (b < 0 or b >= 64) return 0;
    \\    const shift: u6 = @as(u6, @truncate(@as(u64, @intCast(b))));
    \\    return @bitCast(@as(u64, @bitCast(a)) >> shift);
    \\}
    \\fn _lia_mod(a: i64, b: i64) i64 {
    \\    if (b == 0) return 0;
    \\    return @rem(a, b);
    \\}
    \\fn _lia_len(x: anytype) i64 {
    \\    const T = @TypeOf(x);
    \\    switch (@typeInfo(T)) {
    \\        .Pointer => |p| {
    \\            if (p.size == .Slice) return @as(i64, @intCast(x.len));
    \\            if (p.size == .One) {
    \\                switch (@typeInfo(p.child)) {
    \\                    .Array => |a| return @as(i64, @intCast(a.len)),
    \\                    else => {},
    \\                }
    \\            }
    \\        },
    \\        .Array => |a| return @as(i64, @intCast(a.len)),
    \\        else => {},
    \\    }
    \\    return 0;
    \\}
;

pub fn pick_target(src: []const u8, explicit: []const u8) []const u8 {
    if (explicit.len > 0 and !argEq(explicit, "auto")) return explicit;
    const zig_code = lin_to_zig(src);
    defer LIA_ALLOC.free(zig_code);
    const full = _lia_cat(ZIG_RUNTIME_PRELUDE, zig_code);
    defer LIA_ALLOC.free(full);
    const tmp_file = ".lin_ast_check.zig";
    if (std.fs.cwd().createFile(tmp_file, .{})) |f| {
        defer f.close();
        f.writeAll(full) catch return "js";
    } else |_| return "js";
    var zb: []const u8 = "zig";
    if (std.fs.openFileAbsolute("/home/k/.local/bin/zig", .{})) |zf| {
        zf.close();
        zb = "/home/k/.local/bin/zig";
    } else |_| {}
    const r = std.process.Child.run(.{
        .allocator = LIA_ALLOC,
        .argv = &.{ zb, "ast-check", tmp_file },
        .max_output_bytes = 64 * 1024,
    }) catch return "js";
    if (r.term == .Exited and r.term.Exited == 0) return "zig";
    return "js";
}

