fn lin_compact(src: []const u8) []const u8 {
    var out = std.ArrayList(u8).init(LIA_ALLOC);
    var lines = std.mem.splitScalar(u8, src, '\n');
    var indent: usize = 0;
    while (lines.next()) |line| {
        const trimmed = std.mem.trim(u8, line, " \t\r");
        if (trimmed.len == 0) continue;
        if (std.mem.startsWith(u8, trimmed, "}")) {
            if (indent > 0) indent -= 1;
        }
        var k: usize = 0;
        while (k < indent) : (k += 1) {
            out.appendSlice("  ") catch {};
        }
        out.appendSlice(trimmed) catch {};
        out.append('\n') catch {};
        if (std.mem.endsWith(u8, trimmed, "{")) {
            indent += 1;
        }
    }
    return out.toOwnedSlice() catch src;
}
fn lin_lint(src: []const u8) []const u8 {
    return cks_lint(src);
}

pub fn main() !void {
    var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena.deinit();
    LIA_ALLOC = arena.allocator();
    const stdout = std.io.getStdOut().writer();
    const stderr = std.io.getStdErr().writer();
    const args = try std.process.argsAlloc(LIA_ALLOC);
    defer std.process.argsFree(LIA_ALLOC, args);
    if (args.len < 2) {
        try stdout.print("2.0.0\n", .{});
        return;
    }
    const cmd = args[1];
    if (argEq(cmd, "version") or argEq(cmd, "-v") or argEq(cmd, "--version")) {
        try stdout.print("2.0.0\n", .{});
        return;
    }
    if (argEq(cmd, "from-js")) {
        var js_path: ?[]const u8 = null;
        var js_out: ?[]const u8 = null;
        var ai: usize = 2;
        while (ai < args.len) : (ai += 1) {
            if (argEq(args[ai], "-o") and ai + 1 < args.len) {
                ai += 1;
                js_out = args[ai];
            } else if (args[ai][0] != '-') js_path = args[ai];
        }
        if (js_path == null) {
            try stderr.print("usage: lin from-js <file.js> [-o out.lin]\n", .{});
            std.process.exit(1);
        }
        const js = try std.fs.cwd().readFileAlloc(LIA_ALLOC, js_path.?, 10 * 1024 * 1024);
        try stdout.print("{s}", .{jss_report(js)});
        const lin_out = jss_from_js(js);
        if (js_out) |op| {
            const f = try std.fs.cwd().createFile(op, .{});
            defer f.close();
            try f.writeAll(lin_out);
            try stdout.print(".out=\"{s}\"\n", .{op});
        } else {
            try stdout.print("{s}", .{lin_out});
        }
        return;
    }
    if (argEq(cmd, "from-c")) {
        var c_path: ?[]const u8 = null;
        var c_out: ?[]const u8 = null;
        var ai: usize = 2;
        while (ai < args.len) : (ai += 1) {
            if (argEq(args[ai], "-o") and ai + 1 < args.len) {
                ai += 1;
                c_out = args[ai];
            } else if (args[ai][0] != '-') c_path = args[ai];
        }
        if (c_path == null) {
            try stderr.print("usage: lin from-c <file.c> [-o out.lin]\n", .{});
            std.process.exit(1);
        }
        const cs = try std.fs.cwd().readFileAlloc(LIA_ALLOC, c_path.?, 10 * 1024 * 1024);
        try stdout.print("{s}", .{cfs_report(cs)});
        const lin_c = cfs_from_c(cs);
        if (c_out) |op| {
            const f = try std.fs.cwd().createFile(op, .{});
            defer f.close();
            try f.writeAll(lin_c);
            try stdout.print(".out=\"{s}\"\n", .{op});
        } else {
            try stdout.print("{s}", .{lin_c});
        }
        return;
    }
    if (argEq(cmd, "rebuild")) {
        const boot = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_zig_bootstrap.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(boot);
        const arr = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_array.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(arr);
        const em = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_zig_emit.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(em);
        const mt = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_zig_match.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(mt);
        const rg = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_regions.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(rg);
        const jx = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_js_expr.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(jx);
        const jf = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_from_js.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(jf);
        const jd = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_js_driver.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(jd);
        const fc = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_from_c.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(fc);
        const lt = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin_lint.lin", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(lt);
        const src = try std.mem.concat(LIA_ALLOC, u8, &.{ boot, "\n", arr, "\n", em, "\n", mt, "\n", rg, "\n", jx, "\n", jf, "\n", jd, "\n", fc, "\n", lt });
        defer LIA_ALLOC.free(src);
        const fns = lin_to_zig(src);
        const host = try std.fs.cwd().readFileAlloc(LIA_ALLOC, "src/lin.zig", 10 * 1024 * 1024);
        defer LIA_ALLOC.free(host);
        const gen_begin = "// LIN-GEN-BEGIN";
        const m_fn = std.mem.indexOf(u8, host, gen_begin) orelse {
            try stderr.print("rebuild: missing LIN-GEN-BEGIN marker\n", .{});
            std.process.exit(1);
        };
        const m_cli = std.mem.indexOf(u8, host, "\nfn argEq(") orelse {
            try stderr.print("rebuild: missing argEq marker\n", .{});
            std.process.exit(1);
        };
        const host_begin = "// LIN-HOST-BEGIN";
        const host_end = "// LIN-HOST-END";
        const hb = std.mem.indexOf(u8, host, host_begin) orelse {
            try stderr.print("rebuild: missing LIN-HOST-BEGIN marker\n", .{});
            std.process.exit(1);
        };
        const he = std.mem.indexOf(u8, host, host_end) orelse {
            try stderr.print("rebuild: missing LIN-HOST-END marker\n", .{});
            std.process.exit(1);
        };
        if (he < hb) {
            try stderr.print("rebuild: LIN-HOST markers out of order\n", .{});
            std.process.exit(1);
        }
        const host_block = host[hb .. he + host_end.len];
        const next = try std.mem.concat(LIA_ALLOC, u8, &.{ host[0..m_fn], gen_begin, "\n", fns, "\n", host_block, "\n", host[m_cli..] });
        defer LIA_ALLOC.free(next);
        const tf = try std.fs.cwd().createFile("src/lin.zig", .{});
        defer tf.close();
        try tf.writeAll(next);
        try stdout.print("@RULEL:LIN_REBUILD:1.0.0\n.rebuilt=\"src/lin.zig\" .fns={d}\n", .{fns.len});
        return;
    }
    if (argEq(cmd, "grammar") or argEq(cmd, "ebnf")) {
        const grammar_ebnf =
            \\@RULEL:LIN_GRAMMAR_EBNF:1.0.0
            \\.spec="Formal Grammar for LIN L1c/L2 Language"
            \\.grammar={
            \\  Program       ::= ( Pragma | Function | Export )*
            \\  Pragma        ::= '@' Ident ( ':' Ident ( ':' Version )? )? ( '{' AttributeList? '}' )?
            \\  Function      ::= '!' Ident '(' ParameterList? ')' ( '->' Type | ':' Type )? '{' Statement* '}'
            \\  ParameterList ::= Parameter ( ',' Parameter )*
            \\  Parameter     ::= Ident ':' Type
            \\  Type          ::= 'int' | 'string' | 'bool' | 'u32' | 'u64' | 'i32' | 'i64' | '[' Number ']' 'int' | 'list[int]' | 'list[string]'
            \\  Statement     ::= Assignment ';' | Return ';' | WhileLoop | IfBranch | ArrayDecl | Expr ';'
            \\  ArrayDecl     ::= Ident ':' '[' Number ']' 'int' ('=' '[' ExprList ']' )?
            \\  Assignment    ::= Ident '=' Expr | Ident '[' Expr ']' '=' Expr
            \\  Return        ::= '^' Expr
            \\  WhileLoop     ::= 'while' '(' Expr ')' '{' Statement* '}' ';'?
            \\  IfBranch      ::= '?' '(' Expr ')' '{' Statement* '}' ( ':' '(' Expr ')' '{' Statement* '}' )* ( ':' '{' Statement* '}' )? ';'?
            \\  Expr          ::= BinaryExpr | UnaryExpr | CallExpr | Atom
            \\  BinaryExpr    ::= Expr BinaryOp Expr
            \\  BinaryOp      ::= '+' | '-' | '*' | '/' | '%' | '&' | '|' | '^' | '<<' | '>>' | '==' | '!=' | '<' | '<=' | '>' | '>=' | '&&' | '||'
            \\  UnaryExpr     ::= ( '~' | '!' | '-' ) Expr
            \\  CallExpr      ::= Ident '(' ( Expr ( ',' Expr )* )? ')'
            \\  Atom          ::= Number | String | Ident | '(' Expr ')'
            \\  Export        ::= '=ex' '{' IdentList '}'
            \\}
        ;
        try stdout.print("{s}\n", .{grammar_ebnf});
        return;
    }
    if (argEq(cmd, "verify") or argEq(cmd, "prove")) {
        if (args.len < 3) {
            try stderr.print("usage: lin verify <file.lin>\n", .{});
            std.process.exit(1);
        }
        const file = try std.fs.cwd().openFile(args[2], .{});
        defer file.close();
        const src = try file.readToEndAlloc(LIA_ALLOC, 10 * 1024 * 1024);
        defer LIA_ALLOC.free(src);
        try vmVerifyFile(LIA_ALLOC, src);
        return;
    }
    if (argEq(cmd, "export-cert")) {
        if (args.len < 4) {
            try stderr.print("usage: lin export-cert <file.lin> <fn_name>\n", .{});
            std.process.exit(1);
        }
        const file = try std.fs.cwd().openFile(args[2], .{});
        defer file.close();
