                try stdout.print(".backend.vm={d}\n.backend.aot={d}\n.backend.jit={d}\n", .{ vm_res, aot_res, jit_res });
                try stdout.print(".disagreement={{\"vm_vs_jit\":{s},\"vm_vs_aot\":{s},\"jit_vs_aot\":{s}}}\n", .{
                    if (vm_res != jit_res) "true" else "false",
                    if (vm_res != aot_res) "true" else "false",
                    if (jit_res != aot_res) "true" else "false",
                });
                try stdout.print(".execution={{vm=\"executed\",jit=\"executed\",aot=\"executed\"}}\n", .{});
                try stdout.print(".verdict=\"REFUTED\"\n.reason=\"backend_divergence\"\n", .{});
                return;
            }

            try stdout.print(".equivalent=true\n", .{});
            if (expected_val) |exp| {
                try stdout.print(".expected={d}\n", .{exp});
                if (actual == exp) {
                    try stdout.print(".verdict=\"CONFIRMED\"\n", .{});
                } else {
                    try stdout.print(".verdict=\"REFUTED\"\n.reason=\"oracle_mismatch\"\n", .{});
                }
            } else {
                if (actual != 0) {
                    try stdout.print(".verdict=\"CONFIRMED\"\n", .{});
                } else {
                    try stdout.print(".verdict=\"REFUTED\"\n.reason=\"oracle_mismatch\"\n", .{});
                }
            }
            return;
        }

        try stdout.print("@RULEL:LIN_HYPOTHESIS_VERDICT:1.0.0\n", .{});
        try stdout.print(".hypothesis=\"{s}\"\n", .{args[2]});
        try stdout.print(".target=\"{s}::{s}\"\n", .{ target_file, fn_name });
        try stdout.print(".actual={d}\n.steps={d}\n", .{ actual, steps });

        if (expected_val) |exp| {
            try stdout.print(".expected={d}\n", .{exp});
            if (actual == exp) {
                try stdout.print(".verdict=\"CONFIRMED\"\n", .{});
            } else {
                try stdout.print(".verdict=\"REFUTED\"\n.reason=\"oracle_mismatch\"\n", .{});
            }
        } else {
            if (actual != 0) {
                try stdout.print(".verdict=\"CONFIRMED\"\n", .{});
            } else {
                try stdout.print(".verdict=\"REFUTED\"\n.reason=\"oracle_mismatch\"\n", .{});
            }
        }
        return;
    }
    if (argEq(cmd, "fmt") or argEq(cmd, "format")) {
        if (args.len < 3) {
            try stderr.print("usage: lin fmt <file.lin>\n", .{});
            std.process.exit(1);
        }
        const file = try std.fs.cwd().openFile(args[2], .{});
        defer file.close();
        const raw = try file.readToEndAlloc(LIA_ALLOC, 10 * 1024 * 1024);
        defer LIA_ALLOC.free(raw);
        const formatted = lin_compact(raw);
        try stdout.print("{s}\n", .{formatted});
        return;
    }
    if (argEq(cmd, "capabilities")) {
        var is_json = false;
        for (args) |a| {
            if (argEq(a, "--json")) is_json = true;
        }
        if (is_json) {
            try stdout.print("{s}\n", .{lin_capabilities_json()});
        } else {
            try stdout.print("{s}\n", .{lin_capabilities_rulel()});
        }
        return;
    }
    if (argEq(cmd, "prompt-export")) {
        try stdout.print("{s}\n", .{lin_prompt_export()});
        return;
    }
    if (argEq(cmd, "js-expr")) {
        if (args.len < 3) {
            try stderr.print("usage: lin js-expr <expression>\n", .{});
            std.process.exit(1);
        }
        try stdout.print("{s}\n", .{jss_e0(args[2])});
        return;
    }
    if (argEq(cmd, "compact")) {
        if (args.len < 3) {
            try stderr.print("usage: lin compact <file.lin>\n", .{});
            std.process.exit(1);
        }
        const file = try std.fs.cwd().openFile(args[2], .{});
        defer file.close();
        const raw = try file.readToEndAlloc(LIA_ALLOC, 10 * 1024 * 1024);
        defer LIA_ALLOC.free(raw);
        try stdout.print("{s}\n", .{lin_compact(raw)});
        return;
    }
    if (argEq(cmd, "spec")) {
        try stdout.print("{s}", .{lin_spec_rulel()});
        return;
    }
    if (argEq(cmd, "lint")) {
        if (args.len < 3) {
            try stderr.print("usage: lin lint <file.lin>\n", .{});
            std.process.exit(1);
        }
        const file = try std.fs.cwd().openFile(args[2], .{});
        defer file.close();
        const raw = try file.readToEndAlloc(LIA_ALLOC, 10 * 1024 * 1024);
        defer LIA_ALLOC.free(raw);
        try stdout.print("{s}\n", .{lin_lint(raw)});
        return;
    }
    if (argEq(cmd, "vm")) {
        if (args.len < 3) {
            try stderr.print("usage: lin vm <file.lin> [fn] [int args...]\n", .{});
            std.process.exit(1);
        }
        const vsrc = try std.fs.cwd().readFileAlloc(LIA_ALLOC, args[2], 10 * 1024 * 1024);
        const mod = try vmBuild(LIA_ALLOC, vsrc);
        if (args.len < 4) {
            var eligible: usize = 0;
            for (mod.fns) |f| {
                if (f.ok) eligible += 1;
            }
            try stdout.print("@RULEL:LIN_VM:1.0.0\n", .{});
            try stdout.print(".engine{{ opcodes=28 overflow=wrapping shifts=lia_compatible step_limit={d} }}\n", .{VM_STEP_LIMIT});
            try stdout.print(".coverage{{ total={d} eligible={d} rejected={d} }}\n", .{ mod.fns.len, eligible, mod.fns.len - eligible });
            try stdout.print(".fns{{\n", .{});
            for (mod.fns) |f| {
                if (f.ok) {
                    try stdout.print("  .fn{{ name=\"{s}\" params={d} status=OK locals={d} code={d} }}\n", .{ f.name, f.nparams, f.nlocals, f.code.len });
                } else {
                    try stdout.print("  .fn{{ name=\"{s}\" params={d} status=REJECTED reason=\"{s}\" }}\n", .{ f.name, f.nparams, f.reject });
                }
            }
            try stdout.print("}}\n", .{});
            return;
        }
        const fi = vmFind(&mod, args[3]) orelse {
            try stderr.print("vm: unknown function: {s}\n", .{args[3]});
            std.process.exit(1);
        };
        if (!mod.fns[fi].ok) {
            try stdout.print("@RULEL:LIN_VM_RUN:1.0.0\n.refused{{ fn=\"{s}\" reason=\"{s}\" }}\n", .{ mod.fns[fi].name, mod.fns[fi].reject });
            std.process.exit(1);
        }
        var argv = std.ArrayList(i64).init(LIA_ALLOC);
        var k: usize = 4;
        while (k < args.len) : (k += 1) {
            const v = std.fmt.parseInt(i64, args[k], 10) catch {
                try stderr.print("vm: bad integer: {s}\n", .{args[k]});
                std.process.exit(1);
            };
            try argv.append(v);
        }
        var steps: u64 = 0;
        const r = vmExec(&mod, fi, argv.items, 0, &steps) catch |err| {
            try stdout.print("@RULEL:LIN_VM_RUN:1.0.0\n.error{{ fn=\"{s}\" code=\"{s}\" steps={d} }}\n", .{ mod.fns[fi].name, @errorName(err), steps });
            std.process.exit(1);
        };
        try stdout.print("@RULEL:LIN_VM_RUN:1.0.0\n.result{{ fn=\"{s}\" value={d} steps={d} }}\n", .{ mod.fns[fi].name, r, steps });
        return;
    }
    if (argEq(cmd, "vm-sweep")) {
        if (args.len < 6) {
            try stderr.print("usage: lin vm-sweep <file.lin> <fn> <start> <count>\n", .{});
            std.process.exit(1);
        }
        const file = try std.fs.cwd().openFile(args[2], .{});
        defer file.close();
        const src = try file.readToEndAlloc(LIA_ALLOC, 10 * 1024 * 1024);
        defer LIA_ALLOC.free(src);
        const mod = try vmBuild(LIA_ALLOC, src);
        const fi = vmFind(&mod, args[3]) orelse {
            try stderr.print("vm-sweep: unknown function {s}\n", .{args[3]});
            std.process.exit(1);
        };
        const start = try std.fmt.parseInt(i64, args[4], 10);
        const count = try std.fmt.parseInt(usize, args[5], 10);
        var checksum: u64 = 0;
        var total_steps: u64 = 0;
        var val = start;
        var i: usize = 0;
        while (i < count) : (i += 1) {
            const call_args = [_]i64{val};
            var steps: u64 = 0;
            const res = try vmExec(&mod, fi, &call_args, 0, &steps);
            total_steps += steps;
            checksum = checksum *% 31 +% @as(u64, @bitCast(res));
            val += 1;
        }
        try stdout.print("@RULEL:LIN_VM_SWEEP:1.0.0\n.fn=\"{s}\" .start={d} .count={d} .checksum={d} .steps={d}\n", .{ args[3], start, count, checksum, total_steps });
        return;
    }
    var target: []const u8 = "auto";
    var out_path: ?[]const u8 = null;
    var file_path: ?[]const u8 = null;
    var ai: usize = 2;
    while (ai < args.len) : (ai += 1) {
        if (argEq(args[ai], "--target") and ai + 1 < args.len) {
            ai += 1;
            target = args[ai];
        } else if (argEq(args[ai], "-o") and ai + 1 < args.len) {
            ai += 1;
            out_path = args[ai];
        } else if (args[ai][0] != '-') file_path = args[ai];
    }
    if (argEq(cmd, "test")) {
        const p = file_path orelse "test";
        if (std.fs.cwd().openDir(p, .{ .iterate = true })) |dir_val| {
            var dir = dir_val;
            defer dir.close();
            var tot: i64 = 0;
            var it = dir.iterate();
            while (try it.next()) |ent| {
                if (ent.kind != .file or !endsLin(ent.name)) continue;
                const full = try std.fs.path.join(LIA_ALLOC, &.{ p, ent.name });
                defer LIA_ALLOC.free(full);
                try stdout.print("{s}: ", .{full});
                const rr = runLinTestFile(full) catch |err| {
                    try stderr.print("test: {s}: {s}\n", .{ full, @errorName(err) });
                    std.process.exit(1);
                };
                defer LIA_ALLOC.free(rr.stdout);
                defer LIA_ALLOC.free(rr.stderr);
                try stdout.writeAll(rr.stdout);
                try stderr.writeAll(rr.stderr);
                switch (rr.term) {
                    .Exited => |c| if (c != 0) std.process.exit(1),
                    else => std.process.exit(1),
                }
                tot += 1;
            }
            try stdout.print("suite {d}\n", .{tot});
            if (std.mem.eql(u8, p, "test")) {
                if (std.fs.cwd().openDir("test/fail", .{ .iterate = true })) |fail_dir_val| {
                    var fail_dir = fail_dir_val;
                    defer fail_dir.close();
                    var fit = fail_dir.iterate();
                    while (try fit.next()) |ent| {
                        if (ent.kind != .file or !endsLin(ent.name)) continue;
                        const full = try std.fs.path.join(LIA_ALLOC, &.{ "test/fail", ent.name });
                        defer LIA_ALLOC.free(full);
                        const bad = try std.fs.cwd().readFileAlloc(LIA_ALLOC, full, 1024 * 1024);
                        defer LIA_ALLOC.free(bad);
                        if (lin_valid_strict(bad) != 0) {
                            try stderr.print("FAIL expected parse error: {s}\n", .{full});
                            std.process.exit(1);
                        }
                        try stdout.print("{s}: ok fail-closed\n", .{full});
                    }
                } else |_| {}
            }
            return;
        } else |_| {}
        const rr = runLinTestFile(p) catch |err| {
            try stderr.print("test: {s}\n", .{@errorName(err)});
            std.process.exit(1);
        };
        defer LIA_ALLOC.free(rr.stdout);
        defer LIA_ALLOC.free(rr.stderr);
        try stdout.writeAll(rr.stdout);
        try stderr.writeAll(rr.stderr);
        switch (rr.term) {
            .Exited => |c| if (c != 0) std.process.exit(1),
            else => std.process.exit(1),
        }
        return;
    }
    if (file_path == null) {
        try stderr.print("Error: missing file\n", .{});
        std.process.exit(1);
    }
    const file = try std.fs.cwd().openFile(file_path.?, .{});
    defer file.close();
    const raw_src = try file.readToEndAlloc(LIA_ALLOC, 10 * 1024 * 1024);
    defer LIA_ALLOC.free(raw_src);
    const src = apply_dynamic_rules_if_present(LIA_ALLOC, raw_src);
    if (argEq(cmd, "check")) {
        if (lin_syntax_valid(src) == 0) {
            try stderr.print("LIN_PARSE\n", .{});
            std.process.exit(1);
        }
        if (lin_type_check(src)) |err_msg| {
            try stderr.print("{s}\n", .{err_msg});
            std.process.exit(1);
        }
        try stdout.print("{s}", .{lin_check_rulel(src)});
        return;
    }
    if (argEq(cmd, "regions")) {
        if (lin_syntax_valid(src) == 0) {
            try stderr.print("LIN_PARSE\n", .{});
            std.process.exit(1);
        }
        try stdout.print("{s}", .{rgs_regions(src)});
        return;
    }
    if (argEq(cmd, "compile")) {
        const chosen = pick_target(src, target);
        const code = if (argEq(chosen, "zig")) _lia_cat(ZIG_RUNTIME_PRELUDE, lin_to_zig(src)) else lin_to_js(src);
        if (out_path) |op| {
            const f = try std.fs.cwd().createFile(op, .{});
            defer f.close();
            try f.writeAll(code);
            try stdout.print("@RULEL:LIN_COMPILE:1.0.0\n.out=\"{s}\" .target=\"{s}\"\n", .{ op, chosen });
        } else try stdout.print("{s}", .{code});
        return;
    }
    try stderr.print("Error: command not in Zig host yet\n", .{});
    std.process.exit(2);
}
